/**
 * C+ (CH-5b): API-клиент stateless-хода `POST /api/chat`
 * (контракты — shared/schemas/chat.ts).
 *
 * Транспорт: SSE (Accept: text/event-stream) — step-события в onStep,
 * финал — ChatResponse; ошибки после hijack — событие {type:"error",
 * code, httpStatus, message} (04-MAJ-2) → ChatApiError. Ошибки ДО hijack
 * (429 rate-limit, 400 schema_invalid, 413, 502) — реальный HTTP
 * (05-MINOR-4): не-OK статус читается из JSON-тела {code, message}.
 */
import {
  ChatResponseSchema,
  ChatSseEventSchema,
  type ChatRequest,
  type ChatResponse,
  type ChatSseErrorCode,
} from "@trigger-helper/shared";

/** Длинные rag-ходы: серверный таймаут хода 300 с — клиент не раньше. */
const CHAT_TIMEOUT_MS = 300_000;

export class ChatApiError extends Error {
  constructor(
    readonly code: ChatSseErrorCode,
    readonly httpStatus: number,
    message: string,
  ) {
    super(message);
    this.name = "ChatApiError";
  }
}

export interface SendChatOptions {
  onStep?: (step: string, text: string) => void;
  timeoutMs?: number;
}

function sseLoopError(message: string): ChatApiError {
  return new ChatApiError("upstream_error", 502, message);
}

/** AbortSignal.timeout бросает DOMException TimeoutError с англ. текстом —
 * локализуем (легаси api.ts делал так же; ревью CH-5b, MINOR-6). */
function mapTransportError(err: unknown): unknown {
  if (
    typeof DOMException !== "undefined" &&
    err instanceof DOMException &&
    err.name === "TimeoutError"
  ) {
    return new ChatApiError(
      "upstream_error",
      504,
      "Превышено время ожидания ответа (5 мин) — попробуй ещё раз",
    );
  }
  return err;
}

export async function sendChat(
  request: ChatRequest,
  opts: SendChatOptions = {},
): Promise<ChatResponse> {
  try {
    return await sendChatInner(request, opts);
  } catch (err) {
    throw mapTransportError(err);
  }
}

async function sendChatInner(
  request: ChatRequest,
  opts: SendChatOptions,
): Promise<ChatResponse> {
  const res = await fetch("/api/chat", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      accept: "text/event-stream",
    },
    body: JSON.stringify(request),
    signal: AbortSignal.timeout(opts.timeoutMs ?? CHAT_TIMEOUT_MS),
  });

if (!res.ok) {
    // До hijack / не-SSE — реальный HTTP-статус (429-ветка клиента).
    const body = (await res.json().catch(() => ({}))) as {
      code?: string;
      message?: string;
    };
    throw new ChatApiError(
      (body.code as ChatSseErrorCode) ?? "upstream_error",
      res.status,
      body.message ?? `HTTP ${res.status}`,
    );
  }

const contentType = res.headers.get("content-type") ?? "";
  if (!contentType.includes("text/event-stream")) {
    // Теоретическая ветка (прокси снял SSE) — плоский JSON-ответ.
    const parsed = ChatResponseSchema.safeParse(await res.json());
    if (!parsed.success) {
      throw sseLoopError("Ответ не прошёл контракт ответа");
    }
    return parsed.data;
  }

if (!res.body) {
    throw sseLoopError("Пустой поток ответа");
  }

if (!res.body) {
    throw sseLoopError("Пустой поток ответа");
  }

const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let done: ChatResponse | null = null;
  const handleEvent = (raw: string): void => {
    if (!raw.startsWith("data: ")) return;
    const payload = raw.slice("data: ".length);
    if (payload === "[DONE]") return;
    let event: unknown;
    try {
      event = JSON.parse(payload);
    } catch {
      return; // битый кадр — пропускаем молча
    }
    const parsed = ChatSseEventSchema.safeParse(event);
    if (!parsed.success) return;
    if (parsed.data.type === "step") {
      opts.onStep?.(parsed.data.step, parsed.data.text);
    } else if (parsed.data.type === "done") {
      done = parsed.data.result;
    } else {
      throw new ChatApiError(
        parsed.data.code,
        parsed.data.httpStatus,
        parsed.data.message,
      );
    }
  };

try {
    while (true) {
      const { value, done: readerDone } = await reader.read();
      if (value) {
        buffer += decoder.decode(value, { stream: true });
        let sep: number;
        while ((sep = buffer.indexOf("\n\n")) >= 0) {
          const part = buffer.slice(0, sep);
          buffer = buffer.slice(sep + 2);
          handleEvent(part);
        }
      }
      if (readerDone) break;
    }
  } catch (err) {
    // Бросили посреди потока (error-событие/таймаут) — сокет не тянем:
    // отменяем reader, иначе он живёт до закрытия сервером (MINOR-6).
    try {
      await reader.cancel();
    } catch {
      /* уже закрыт */
    }
    throw err;
  }

if (!done) {
    throw sseLoopError("Поток оборвался без ответа");
  }
  const checked = ChatResponseSchema.safeParse(done);
  if (!checked.success) {
    throw sseLoopError("Финальный ответ не прошёл контракт");
  }
  return checked.data;
}

/**
 * UNIT — api.ragStats: zod-контракт «Поиск по базе» (RagStatsResponseSchema).
 * Фикстура — РЕАЛЬНЫЙ прод-ответ GET /api/rag/stats (30.09.2026, h3llo),
 * дословно (см. e2eRagStats в e2e/fixtures.ts). Директива заказчика после
 * бага «прочерков»: экран писали против выдуманной формы без контракта —
 * поэтому прод-форма обязана парситься, экстра-поля (dim, latencyMs,
 * compare.generatedAt) не ломают parse, чужая форма → управляемая ApiError.
 */
import { beforeEach, describe, expect, it } from "vitest";
import { ApiError, api } from "./api";
import { e2eRagStats } from "../../e2e/fixtures";
import { stubFetch } from "../test/http";

beforeEach(() => {
  stubFetch([{ url: "/api/rag/stats", json: e2eRagStats() }]);
});

describe("api.ragStats · контракт «Поиск по базе»", () => {
  it("реальный прод-ответ парсится: 2 индекса, чанки 128/220, compare по стратегиям", async () => {
    const stats = await api.ragStats();

expect(stats.ok).toBe(true);
    expect(stats.indexes).toHaveLength(2);
    expect(stats.indexes[0]).toMatchObject({
      strategy: "fixed",
      model: "Xenova/multilingual-e5-small",
      chunks: 128,
      fileCount: 43,
    });
    expect(stats.indexes[1]).toMatchObject({ strategy: "structured", chunks: 220 });
    expect(stats.indexes[0]?.builtAt).toBe("2026-09-30T08:41:44.756Z");

const byStrategy = stats.compare?.byStrategy ?? {};
    expect(byStrategy.structured?.hitAt1).toBeCloseTo(0.6667, 4);
    expect(byStrategy.fixed).toMatchObject({ hitAt1: 0.5, hitAt5: 0.9167, mrr: 0.6736 });
    expect(byStrategy.structured).toMatchObject({ hitAt5: 0.8333, mrr: 0.7619 });
  });

it("экстра-поля прода (dim, latencyMs, compare.generatedAt) не ломают parse и срезаются схемой", async () => {
    const stats = await api.ragStats(); // resolve, а не ApiError — главное

// parse прошёл именно через схему: неизвестные ключи в вывод не прошли
    expect(stats.indexes[0]).not.toHaveProperty("dim");
    expect(stats).not.toHaveProperty("latencyMs");
    expect(stats.compare).not.toHaveProperty("generatedAt");
  });

it("чужая форма ({ok:false, indexes:'x'}) → ApiError «Неожиданный формат ответа сервера» (502), не мусор в UI", async () => {
    stubFetch([{ url: "/api/rag/stats", json: { ok: false, indexes: "x" } }]);

const err = await api.ragStats().catch((e: unknown) => e);

expect(err).toBeInstanceOf(ApiError);
    expect((err as ApiError).message).toBe("Неожиданный формат ответа сервера");
    expect((err as ApiError).status).toBe(502);
  });
});

/**
 * Типизированный REST-клиент SPA (P0-подмножество, design §3.1).
 * C+ CH-6 (D-10): stateful-обёртки (instances, /api/agent/run, messages,
 * chat-task-state, close/restore) сняты вместе с серверными роутами — ход
 * диалога идёт через api-chat.ts (stateless POST /api/chat, SSE); остались
 * только справочники. День 26: схема /api/models — СОВМЕСТНАЯ (shared
 * schemas/models.ts), не локальная: локальный zod strip-ал бы новую
 * local-секцию каталога локальных моделей (D-26-4), и она молча не дошла
 * бы до UI (04-MED-3).
 */
import { z } from "zod";
import { ModelsResponseSchema } from "@trigger-helper/shared";

/** Ошибка API: текст для пользователя + статус + сырое тело. */
export class ApiError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: unknown = null,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

/** Дефолтный таймаут запроса: зависший fetch ≠ «молча пустой UI» (баг 1). */
const DEFAULT_TIMEOUT_MS = 20_000;

/** Дефолтный таймаут запроса: зависший fetch ≠ «молча пустой UI» (баг 1). */
const DEFAULT_TIMEOUT_MS = 20_000;

/** Низкоуровневый fetch: JSON туда/обратно, не-2xx → ApiError. */
async function request(path: string, init?: RequestInit, timeoutMs = DEFAULT_TIMEOUT_MS): Promise<unknown> {
  let res: Response;
  try {
    res = await fetch(path, {
      ...init,
      signal: AbortSignal.timeout(timeoutMs),
      headers: {
        ...(init?.body ? { "content-type": "application/json" } : {}),
        ...init?.headers,
      },
    });
  } catch (e) {
    const msg = e instanceof DOMException && e.name === "TimeoutError"
      ? `Сервер не ответил за ${Math.round(timeoutMs / 1000)} с`
      : "Сервер недоступен";
    throw new ApiError(msg, 0, e);
  }
  const text = await res.text();
  let data: unknown = null;
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = text;
    }
  }
  if (!res.ok) {
    const msg =
      typeof data === "object" &&
      data !== null &&
      "error" in data &&
      typeof (data as { error: unknown }).error === "string"
        ? (data as { error: string }).error
        : res.statusText || `HTTP ${res.status}`;
    throw new ApiError(msg, res.status, data);
  }
  return data;
}

/** Парс ответа схемой; расхождение контракта → явная ошибка, не «мусор в UI».
 *  Структурная сигнатура (safeParse → T), а не z.ZodType<T>: у схем с .default()
 *  Input ≠ Output, и вариантность ZodType ломает вывод типов. */
function parseWith<T>(schema: { safeParse: (data: unknown) => z.SafeParseReturnType<unknown, T> }, data: unknown): T {
  const r = schema.safeParse(data);
  if (!r.success) {
    throw new ApiError("Неожиданный формат ответа сервера", 502, r.error);
  }
  return r.data;
}

/** Элемент models[] ответа /api/models (после трима 04.10 — только поля SPA). */
export type ModelInfo = ModelsResponse["models"][number];

/** GET /api/rag/stats — статистика индексов и контрольные прогоны (read-only). */
const RagStatsResponseSchema = z.object({
  ok: z.boolean(),
  indexes: z.array(
    z.object({
      strategy: z.string(),
      model: z.string(),
      chunks: z.number(),
      fileCount: z.number(),
      builtAt: z.string().optional(),
      avgChars: z.number().optional(),
    }),
  ),
  compare: z
    .object({
      byStrategy: z.record(
        z.string(),
        z.object({
          hitAt1: z.number().optional(),
          hitAt5: z.number().optional(),
          mrr: z.number().optional(),
        }),
      ),
    })
    .optional(),
});

/** GET /api/agents — метa-справочник; настройкам нужен дефолт автосжатия
 * (QA 041004: поле «Автосжатие» рисовалось пустым — override не задан,
 * а серверный дефолт UI не знал). Остальные поля ответа стриппаются zod'ом. */
const AgentsMetaResponseSchema = z.object({
  autoCompress: z.object({ defaultEvery: z.number().int() }).optional(),
});

export type ModelsResponse = z.infer<typeof ModelsResponseSchema>;

export const api = {
  async getModels(): Promise<ModelsResponse> {
    return parseWith(ModelsResponseSchema, await request("/api/models"));
  },

/** GET /api/agents — справочник пресетов/дефолтов (нужен defaultEvery). */
  async agentsMeta(): Promise<z.infer<typeof AgentsMetaResponseSchema>> {
    return parseWith(AgentsMetaResponseSchema, await request("/api/agents"));
  },

/** GET /api/rag/stats — read-only статистика индексов (экран настроек). */
  async ragStats(): Promise<z.infer<typeof RagStatsResponseSchema>> {
    return parseWith(RagStatsResponseSchema, await request("/api/rag/stats"));
  },
};

/**
 * UNIT — локальное состояние ходов (C+ CH-5b + хвосты волны): applyTurnResult
 * (пара Q/A, merge memoryDelta, инлайн-сжатие заменяет префикс), композер
 * buildContextTail (включая блоки задача/инварианты/профиль — день 12–14),
 * локальный PATCH памяти задачи, триггер сжатия; export видит все коллекции
 * (threads + threadState + profiles).
 */
import { beforeEach, describe, expect, it } from "vitest";
import type { ChatResponse, InvariantRow } from "@trigger-helper/shared";
import {
  buildExportFile,
  applyImportFile,
  threadsCollection,
} from "./storage/th-local";
import {
  applyTurnResult,
  buildContextTail,
  createTask,
  createThread,
  getThreadState,
  patchChatTask,
  sendTaskCommand,
  setInvariants,
  shouldCompressNow,
  threadStateCollection,
} from "./chat-state";
import {
  profilesCollection,
  getActiveProfile,
  setActiveProfile,
  upsertProfile,
} from "./profile-state";

const usage = {
  model: "deepseek-chat",
  prompt_tokens: 10,
  completion_tokens: 5,
  total_tokens: 15,
  prompt_cache_hit_tokens: 0,
  prompt_cache_miss_tokens: 10,
  estimated_cost_usd: 0.001,
  estimated_cost_rub: 0,
};

const ok = (reply: string, over: Partial<ChatResponse> = {}): ChatResponse => ({
  reply,
  trace: { historyMessages: [] },
  usage,
  ...over,
});

const ok = (reply: string, over: Partial<ChatResponse> = {}): ChatResponse => ({
  reply,
  trace: { historyMessages: [] },
  usage,
  ...over,
});

// Чистка через сами коллекции (replaceAll пишет пустой конверт в их
// localStorage-ключи): прямой доступ к глобалу localStorage в тестовом
// воркере нестабилен — коллекции ходят через тот же акцессор, что и прод.
beforeEach(() => {
  threadsCollection.replaceAll([]);
  threadStateCollection.replaceAll([]);
  profilesCollection.replaceAll([]);
});

describe("applyTurnResult — ход → локальное состояние", () => {
  it("пара Q/A пишется в диалог, title из первого ввода", () => {
    createThread("t1", "care", "");
    const { thread } = applyTurnResult(
      "t1",
      "care",
      "болит шея",
      ok("проверь мышцу"),
    );
    expect(thread.title).toBe("болит шея");
    expect(thread.dialogue).toEqual([
      { role: "user", content: "болит шея" },
      { role: "assistant", content: "проверь мышцу" },
    ]);
  });

it("memoryDelta мержится: факты + память задачи (Q-3)", () => {
    createThread("t2", "rag_chat", "тред");
    const { state } = applyTurnResult(
      "t2",
      "rag_chat",
      "болит под лопаткой, хочу понять причину",
      ok("ищи ромбообразную", {
        memoryDelta: {
          facts: [{ text: "боль под лопаткой", suggestedLayer: "working" }],
          chatTask: { goal: "понять причину боли" },
        },
      }),
    );
    expect(state.memory.facts).toHaveLength(1);
    expect(state.chatTask.goal).toBe("понять причину боли");
    // и хвост это несёт: memory + chatTask в contextTail
    const tail = buildContextTail("t2");
    expect(tail.memory?.facts).toHaveLength(1);
    expect(tail.chatTask?.goal).toBe("понять причину боли");
  });

it("compress: сводка одна (не стек), диалог = keptTail + пара хода (Q-2)", () => {
    createThread("t3", "care", "тред");
    // 6 сообщений до хода — чтобы было что сжимать
    for (let i = 0; i < 3; i++) {
      applyTurnResult("t3", "care", `вопрос ${i}`, ok(`ответ ${i}`));
    }
    const { thread } = applyTurnResult(
      "t3",
      "care",
      "итоговый вопрос",
      ok("итоговый ответ", {
        compress: {
          summary: "раньше обсуждали шею",
          keptTail: [{ role: "user", content: "вопрос 2" }],
        },
      }),
    );
    expect(thread.summaries).toEqual(["раньше обсуждали шею"]);
    expect(thread.dialogue).toEqual([
      { role: "user", content: "вопрос 2" },
      { role: "user", content: "итоговый вопрос" },
      { role: "assistant", content: "итоговый ответ" },
    ]);
  });

it("триггер сжатия считает по локальному диалогу", () => {
    createThread("t4", "care", "тред");
    expect(shouldCompressNow("t4", 10)).toBe(false);
    for (let i = 0; i < 7; i++) {
      applyTurnResult("t4", "care", `в${i}`, ok(`о${i}`));
    }
    expect(shouldCompressNow("t4", 10)).toBe(true); // 14 - 4 = 10 ≥ 10
  });
});

describe("patchChatTask — локальная панель day25", () => {
  it("PATCH правит только указанные поля", () => {
    createThread("t5", "rag_chat", "тред");
    applyTurnResult(
      "t5",
      "rag_chat",
      "в",
      ok("о", {
        memoryDelta: { facts: [], chatTask: { goal: "старая цель" } },
      }),
    );
    patchChatTask("t5", { goal: "новая цель" });
    const state = getThreadState("t5");
    expect(state.chatTask.goal).toBe("новая цель");
  });
});

describe("export/import видит все коллекции", () => {
  it("buildExportFile несёт threads, threadState и profiles", () => {
    createThread("t6", "care", "тред");
    applyTurnResult(
      "t6",
      "care",
      "в",
      ok("о", {
        memoryDelta: {
          facts: [{ text: "факт", suggestedLayer: "short" }],
          chatTask: { goal: "цель" },
        },
      }),
    );
    const file = buildExportFile();
    expect(Object.keys(file.collections).sort()).toEqual([
      "profiles",
      "threadState",
      "threads",
    ]);
    expect(file.collections.threadState).toHaveLength(1);
    // round-trip: «чистое устройство» → импорт → состояние на месте
    threadsCollection.replaceAll([]);
    threadStateCollection.replaceAll([]);
    const result = applyImportFile(file);
    expect(result).toMatchObject({
      ok: true,
      imported: { threads: 1, threadState: 1 },
    });
    expect(buildContextTail("t6").memory?.facts).toHaveLength(1);
  });
});

describe("задача-FSM (день 13) — хранение + композер", () => {
  it("createTask → contextTail.task; ход не затирает задачу", () => {
    createThread("t7", "care", "тред");
    createTask("t7", {
      id: "task-1",
      title: "убрать боль в шее",
      plan: ["найти мышцу", "массаж", "проверить"],
    });
    expect(buildContextTail("t7").task?.title).toBe("убрать боль в шее");
    applyTurnResult("t7", "care", "в", ok("о"));
    expect(getThreadState("t7").task?.stage).toBe("planning");
  });

it("команды: goto по карте, пауза морозит, done требует согласия", () => {
    createThread("t8", "care", "тред");
    createTask("t8", { id: "task-2", title: "т", plan: ["ш1", "ш2"] });
    // planning → execution — разрешено
    const gotoExec = sendTaskCommand("t8", { action: "goto", to: "execution" });
    expect(gotoExec.result?.kind).toBe("ok");
    expect(getThreadState("t8").task?.stage).toBe("execution");
    // шаг вперёд — execution-only
    const step = sendTaskCommand("t8", { action: "next_step" });
    expect(step.result?.kind).toBe("ok");
    expect(getThreadState("t8").task?.step).toBe(2);
    // пауза морозит переходы
    sendTaskCommand("t8", { action: "pause" });
    const frozen = sendTaskCommand("t8", { action: "goto", to: "validation" });
    expect(frozen.result).toMatchObject({ kind: "invalid" });
    sendTaskCommand("t8", { action: "resume" });
    // execution → done запрещён картой (только через validation)
    const badDone = sendTaskCommand("t8", { action: "goto", to: "done", consent: true });
    expect(badDone.result).toMatchObject({ kind: "invalid" });
    // validation → done без согласия — consentRequired
    sendTaskCommand("t8", { action: "goto", to: "validation" });
    const noConsent = sendTaskCommand("t8", { action: "goto", to: "done" });
    expect(noConsent.result).toMatchObject({ kind: "invalid", consentRequired: true });
    const consent = sendTaskCommand("t8", { action: "goto", to: "done", consent: true });
    expect(consent.result?.kind).toBe("ok");
    expect(getThreadState("t8").task?.stage).toBe("done");
  });
});

describe("инварианты (день 14) — в хвост идут только активные", () => {
  it("setInvariants фильтруется по active в композере", () => {
    createThread("t9", "care", "тред");
    const now = new Date().toISOString();
    const rows: InvariantRow[] = [
      { id: "i1", text: "не рекомендуй задержку дыхания", scope: "agent", enforcement: "hard", pattern: "задерж", active: true, createdAt: now, updatedAt: now },
      { id: "i2", text: "отвечай коротко", scope: "agent", enforcement: "soft", active: false, createdAt: now, updatedAt: now },
    ];
    setInvariants("t9", rows);
    const tail = buildContextTail("t9");
    expect(tail.invariants).toHaveLength(1);
    expect(tail.invariants[0]?.id).toBe("i1");
    // ход не затирает редакцию владельца
    applyTurnResult("t9", "care", "в", ok("о"));
    expect(getThreadState("t9").invariants).toHaveLength(2);
