/**
 * C+ хвосты (день 12 → клиент, D-4): профили персонализации — глобальная
 * коллекция th.profiles.v1, одна запись {id:"global", profiles, activeProfileId}
 * (наследование семантики «instance-level router»: один активный профиль).
 * Композер contextTail берёт активный профиль; export/import подхватывает
 * коллекцию реестром автоматически (CH-2).
 */
import { z } from "zod";
import { UserProfileSchema, type UserProfile } from "@trigger-helper/shared";
import { LocalCollection, registerLocalCollection } from "./storage/th-local";

export const PROFILES_MAX = 8;

const ProfileStateRecordSchema = z.object({
  id: z.literal("global"),
  profiles: z.array(UserProfileSchema).max(PROFILES_MAX).default([]),
  activeProfileId: z.string().min(1).nullable().default(null),
});
export type ProfileStateRecord = z.infer<typeof ProfileStateRecordSchema>;

/** Глобальное состояние профилей; ключ — единственная запись "global". */
export const profilesCollection = new LocalCollection({
  name: "profiles",
  version: 1,
  schema: ProfileStateRecordSchema,
  maxRecords: 1,
});
registerLocalCollection(profilesCollection); // export/import видит всё

const EMPTY: ProfileStateRecord = {
  id: "global",
  profiles: [],
  activeProfileId: null,
};

export function getProfileState(): ProfileStateRecord {
  return profilesCollection.get("global") ?? EMPTY;
}

/** Активный профиль для contextTail (null = блок profile не шлётся). */
export function getActiveProfile(): UserProfile | null {
  const s = getProfileState();
  if (!s.activeProfileId) return null;
  return s.profiles.find((p) => p.id === s.activeProfileId) ?? null;
}

function putState(next: Omit<ProfileStateRecord, "id">): ProfileStateRecord {
  const record = { ...next, id: "global" as const };
  profilesCollection.put(record);
  return record;
}

/** Добавить/обновить профиль (id — за вызывающим: uid()). */
export function upsertProfile(profile: UserProfile): ProfileStateRecord {
  const s = getProfileState();
  const exists = s.profiles.some((p) => p.id === profile.id);
  const profiles = exists
    ? s.profiles.map((p) => (p.id === profile.id ? profile : p))
    : [...s.profiles, profile].slice(0, PROFILES_MAX);
  return putState({ ...s, profiles });
}

export function removeProfile(id: string): ProfileStateRecord {
  const s = getProfileState();
  return putState({
    profiles: s.profiles.filter((p) => p.id !== id),
    activeProfileId: s.activeProfileId === id ? null : s.activeProfileId,
  });
}

/** Активный профиль (null — без персонализации). */
export function setActiveProfile(id: string | null): ProfileStateRecord {
  const s = getProfileState();
  if (id !== null && !s.profiles.some((p) => p.id === id)) return s;
  return putState({ ...s, activeProfileId: id });
}

/**
 * P2: связный скролл диалог ↔ трейс (D-2, требование Кости дословно:
 * «чтобы ответы пользователю и трейсы были синхронизированы»).
 * Leader-by-intent: ведёт та колонка, которую скроллит пользователь;
 * программный скролл ведомого прикрыт guard-флагом (scrollend/hard-cap),
 * чтобы не было ping-pong. Якорь пары — data-turn-id (бабл ↔ блок хода).
 */

export interface ScrollSyncOptions {
  /** Отступ «линии фокуса» от верха колонки. */
  offsetPx?: number;
  /** Ход, встал на линию фокуса (индикатор «ход в фокусе»). */
  onTurnFocus?: (turnId: string | null) => void;
}

/** Hard-cap guard: даже без scrollend программная анимация не длиннее. */
const HARD_GUARD_MS = 800;

function anchors(el: HTMLElement): HTMLElement[] {
  return Array.from(el.querySelectorAll<HTMLElement>("[data-turn-id]"));
}

/** Якорь на линии фокуса: первый элемент, чей низ ниже линии; ниже всех — последний. */
function anchorAtLine(container: HTMLElement, offsetPx: number): HTMLElement | null {
  const line = container.getBoundingClientRect().top + offsetPx;
  const list = anchors(container);
  for (const el of list) {
    if (el.getBoundingClientRect().bottom >= line) return el;
  }
  return list[list.length - 1] ?? null;
}

export function linkScroll(
  a: HTMLElement,
  b: HTMLElement,
  opts: ScrollSyncOptions = {},
): { dispose: () => void; alignTo: (turnId: string) => void } {
  const offsetPx = opts.offsetPx ?? 56;
  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  let guardUntil = 0;
  let disposed = false;

/** Прокрутить контейнер так, чтобы якорь хода встал на линию фокуса. */
  const scrollToAnchor = (container: HTMLElement, el: HTMLElement): void => {
    const cr = container.getBoundingClientRect();
    const er = el.getBoundingClientRect();
    const top = container.scrollTop + (er.top - cr.top) - offsetPx;
    guardUntil = performance.now() + HARD_GUARD_MS;
    container.scrollTo({ top: Math.max(0, top), behavior: reduced ? "auto" : "smooth" });
  };

const follow = (leader: HTMLElement, follower: HTMLElement): void => {
    if (performance.now() < guardUntil) return; // это наш программный скролл
    const anchor = anchorAtLine(leader, offsetPx);
    const turnId = anchor?.dataset.turnId ?? null;
    opts.onTurnFocus?.(turnId);
    if (!anchor || !turnId) return;
    const target = anchors(follower).find((el) => el.dataset.turnId === turnId);
    if (!target) return;
    scrollToAnchor(follower, target);
  };

const onA = (): void => {
    if (!disposed) follow(a, b);
  };
  const onB = (): void => {
    if (!disposed) follow(b, a);
  };
  const clearGuard = (): void => {
    guardUntil = 0;
  };

a.addEventListener("scroll", onA, { passive: true });
  b.addEventListener("scroll", onB, { passive: true });
  a.addEventListener("scrollend", clearGuard);
  b.addEventListener("scrollend", clearGuard);

a.addEventListener("scroll", onA, { passive: true });
  b.addEventListener("scroll", onB, { passive: true });
  a.addEventListener("scrollend", clearGuard);
  b.addEventListener("scrollend", clearGuard);

/** Кликовая синхронизация (Костя 04.10): клик по ходу/баблу — обе колонки
   *  ставят этот ход на линию фокуса (недостающий якорь пропускается). */
  const alignTo = (turnId: string): void => {
    if (disposed) return;
    const aAnchor = anchors(a).find((el) => el.dataset.turnId === turnId);
    const bAnchor = anchors(b).find((el) => el.dataset.turnId === turnId);
    if (aAnchor) scrollToAnchor(a, aAnchor);
    if (bAnchor) setTimeout(() => !disposed && scrollToAnchor(b, bAnchor), 40);
    opts.onTurnFocus?.(turnId);
  };

const dispose = (): void => {
    disposed = true;
    a.removeEventListener("scroll", onA);
    b.removeEventListener("scroll", onB);
    a.removeEventListener("scrollend", clearGuard);
    b.removeEventListener("scrollend", clearGuard);
  };

return { dispose, alignTo };
}

/**
 * UNIT — клиентский storage-слой C+ (CH-2, D-3/D-7): localStorage-коллекции
 * th.<name>.v<N> (per-record safeParse-drop, write-behind debounce, квота
 * НЕ чистит данные пользователя), export {format, version, savedAt,
 * collections}, импорт «последний выигрывает».
 */
import { beforeEach, describe, expect, it, vi } from "vitest";
import {
  EXPORT_FORMAT,
  ExportFileSchema,
  ChatThreadRecordSchema,
  type ChatThreadRecord,
} from "@trigger-helper/shared";
import {
  applyImportFile,
  buildExportFile,
  LocalCollection,
} from "./th-local";

function thread(id: string, over: Partial<ChatThreadRecord> = {}): ChatThreadRecord {
  return {
    id,
    preset: "care",
    title: `Тред ${id}`,
    createdAt: "2026-10-05T10:00:00Z",
    updatedAt: "2026-10-05T10:00:00Z",
    summaries: [],
    dialogue: [
      { role: "user", content: "болит шея" },
      { role: "assistant", content: "проверь мышцу сбоку" },
    ],
    ...over,
  };
}

function realCollection(maxRecords?: number): LocalCollection<ChatThreadRecord> {
  return new LocalCollection({
    name: "threads",
    version: 1,
    schema: ChatThreadRecordSchema,
    maxRecords,
  });
}

beforeEach(() => {
  localStorage.clear();
});

describe("LocalCollection — load/save", () => {
  it("round-trip: put → flush → новый экземпляр читает то же", () => {
    const c = realCollection();
    c.put(thread("a"));
    c.put(thread("b"));
    c.flushNow();
    const reloaded = realCollection();
    expect(reloaded.all().map((t) => t.id)).toEqual(["a", "b"]);
    expect(reloaded.get("a")?.dialogue).toHaveLength(2);
  });

it("битая запись падает одна (safeParse-drop + warn), не хранилище", () => {
    const good = thread("good");
    const envelope = {
      version: 1,
      records: [good, { id: "bad", preset: "no-such-preset" }],
    };
    localStorage.setItem("th.threads.v1", JSON.stringify(envelope));
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    const c = realCollection();
    expect(c.all().map((t) => t.id)).toEqual(["good"]);
    expect(warn).toHaveBeenCalled();
    warn.mockRestore();
  });

it("версия в конверте ≠ версии коллекции — игнор (чистый старт)", () => {
    localStorage.setItem(
      "th.threads.v1",
      JSON.stringify({ version: 2, records: [thread("x")] }),
    );
    expect(realCollection().all()).toEqual([]);
  });

it("maxRecords: сверх капа выселяется старейшая", () => {
    const c = realCollection(3);
    for (const id of ["a", "b", "c", "d"]) c.put(thread(id));
    expect(c.all().map((t) => t.id)).toEqual(["b", "c", "d"]);
  });

it("upsert существующего id не размножает запись", () => {
    const c = realCollection();
    c.put(thread("a", { title: "было" }));
    c.put(thread("a", { title: "стало" }));
    expect(c.all()).toHaveLength(1);
    expect(c.get("a")?.title).toBe("стало");
  });

it("write-behind: запись уходит через debounce 500 мс", () => {
    vi.useFakeTimers();
    const c = realCollection();
    c.put(thread("a"));
    expect(localStorage.getItem("th.threads.v1")).toBeNull();
    vi.advanceTimersByTime(500);
    expect(localStorage.getItem("th.threads.v1")).not.toBeNull();
    vi.useRealTimers();
  });

it("квота: setItem падает — warn, данные в памяти целы, ретрай пишет", () => {
    const spy = vi
      .spyOn(Storage.prototype, "setItem")
      .mockImplementationOnce(() => {
        throw new Error("QuotaExceededError");
      });
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    const c = realCollection();
    c.put(thread("a"));
    c.flushNow(); // первый setItem — бросает
    expect(c.all()).toHaveLength(1); // в памяти жива
    c.flushNow(); // ретрай — реальный setItem
    expect(realCollection().all().map((t) => t.id)).toEqual(["a"]);
    // и никакой removeItem-чистки данных (D-7): ключ не стёрт при отказе
    spy.mockRestore();
    warn.mockRestore();
  });
});

