    expect(t.turns).toBe(2);
    expect(t.railTotal).toBe(0);
    trace.addTurnFromChat("вопрос", makeChatResponse({ rag: ragOkPayload("q") }), "live1");
    t = trace.totals();
    expect(t.railTotal).toBe(1);
    expect(t.railOk).toBe(1);
  });

