export type TraceStepKind =
  | "llm"
  | "rag"
  | "memory"
  | "compress"
  | "gate"
  | "fsm"
  | "payload"
  | "tool";

export type TraceStepKind =
  | "llm"
  | "rag"
  | "memory"
  | "compress"
  | "gate"
  | "fsm"
  | "payload"
