// Окно try — с первого шага после hijack (051005): ранний throw
    // больше не вешает поток.
    try {
      const parsed = ChatRequestSchema.safeParse(request.body);
      if (!parsed.success) {
        const message = parsed.error.issues
          .map((i) => `${i.path.join(".") || "body"}: ${i.message}`)
          .join("; ");
