        : null;

const taskCheck = checkTask(
        secondResult ? secondResult.reply : firstResult.reply,
      );
      const invariantCheck = checkInvariants(
        secondResult ? secondResult.reply : firstResult.reply,
      );
      const retried = secondResult !== null;

const taskCheck = checkTask(
        secondResult ? secondResult.reply : firstResult.reply,
