/**
 * Day32 · режим PR: AI-ревью реального pull request на GitHub (буквальный
 * минимум задания — «пайплайн запускается на PR»). Публичный outbox
 * читается без токена; приватный product-репо — с GITHUB_TOKEN в env.
 *
 *   npm run review:pr -- 7                                  (outbox по умолчанию)
 *   npm run review:pr -- 7 --repo=kosvitko/trigger-helper
 *
 * Выход: 0 — ревью получено (вердикт informational); 1 — сбой (нет PR/сеть).
 */

const DEFAULT_REPO = "kosvitko/trigger-helper-advent";
const GH_API = "https://api.github.com";

type PrMeta = { title?: string; changed_files?: number; head?: { sha?: string } };

async function ghText(path: string, accept: string): Promise<string> {
  const headers: Record<string, string> = {
    Accept: accept,
    "User-Agent": "trigger-helper-review",
  };
  if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  const response = await fetch(`${GH_API}${path}`, {
    headers,
    signal: AbortSignal.timeout(30_000),
  });
  if (!response.ok) {
    const body = await response.text().catch(() => "");
    throw new Error(`GitHub API ${response.status} ${path}: ${body.slice(0, 200)}`);
  }
  return response.text();
}

async function main(): Promise<number> {
  const args = process.argv.slice(2);
  const prArg = args.find((a) => /^\d+$/.test(a));
  const repoArg = args.find((a) => a.startsWith("--repo="));
  const repo = repoArg ? repoArg.slice("--repo=".length) : DEFAULT_REPO;
  if (!prArg) {
    console.error("Использование: npm run review:pr -- <номер-PR> [--repo=owner/name]");
    return 1;
  }
  const pr = Number(prArg);
  const env = loadEnv();
  console.log(`[review:pr] PR #${pr} · ${repo}`);
  try {
    const metaRaw = await ghText(`/repos/${repo}/pulls/${pr}`, "application/vnd.github+json");
    const meta = JSON.parse(metaRaw) as PrMeta;
    const diff = await ghText(`/repos/${repo}/pulls/${pr}`, "application/vnd.github.diff");
    const filesRaw = await ghText(
      `/repos/${repo}/pulls/${pr}/files?per_page=100`,
      "application/vnd.github+json",
    );
    const files = (JSON.parse(filesRaw) as Array<{ filename?: string; status?: string }>)
      .filter((f) => typeof f.filename === "string")
      .map((f): ReviewFile => ({ status: f.status ?? "M", path: f.filename! }));

const service = createReviewService({ env });
    const result = await service.review({
      source: `PR #${pr} ${repo}`,
      title: meta.title ?? "",
      files,
      diff,
    });
    const artifact = await saveReviewArtifact(result);
    printReview(result, artifact);
    return 0;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`[review:pr] сбой: ${message}`);
    return 1;
  }
}

process.exit(await main());

import { loadEnv } from "../config/env.js";
import { createReviewService } from "../services/review.js";
import {
  collectRange,
  printReview,
  resolvePushRange,
  saveReviewArtifact,
} from "./review-common.js";

/**
 * Day32 · строгий режим pre-push (гейт Кости 261013: «пуш только после
 * approve; нет approve — нет пуша»). Вызывается хуком .githooks/pre-push:
 *
 *   npm run review:push -- <local_ref> <local_sha> <remote_ref> <remote_sha>
 *
 * Без аргументов читает те же строки со stdin (ручной запуск/отладка).
 * Выход: 0 — все пушимые диапазоны approved (пуш продолжается);
 *        1 — блок: вердикт changes_requested или сбой ревью (strict).
 * Обход (осознанный, виден в истории shell): REVIEW_SKIP=1 | git push --no-verify.
 */

const ZEROS = "0".repeat(40);

type RefLine = { localRef: string; localSha: string; remoteRef: string; remoteSha: string };

async function readRefLines(args: string[]): Promise<RefLine[]> {
  if (args.length >= 4) {
    return [{ localRef: args[0]!, localSha: args[1]!, remoteRef: args[2]!, remoteSha: args[3]! }];
  }
  const chunks: string[] = [];
  for await (const chunk of process.stdin) chunks.push(String(chunk));
  return chunks
    .join("")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const [localRef, localSha, remoteRef, remoteSha] = line.split(/\s+/);
      return localRef && localSha && remoteRef && remoteSha
        ? { localRef, localSha, remoteRef, remoteSha }
        : null;
    })
    .filter((ref): ref is RefLine => ref !== null);
}

async function main(): Promise<number> {
  if (process.env.REVIEW_SKIP === "1") {
    console.log("[review:push] REVIEW_SKIP=1 — ревью пропущено");
    return 0;
  }
  const refLines = await readRefLines(process.argv.slice(2));
  if (refLines.length === 0) {
    console.log("[review:push] нет пушимых рефов — ок");
    return 0;
  }
  const env = loadEnv();
  const service = createReviewService({ env });
  let approved = true;

for (const ref of refLines) {
    if (ref.localSha === ZEROS) continue; // удаление remote-рефа — не ревьюим
    const range = await resolvePushRange(ref.localSha, ref.remoteSha);
    console.log(`[review:push] ${ref.localRef} → ${ref.remoteRef} · диапазон ${range}`);
    const { files, diff } = await collectRange(range);
    if (!diff.trim()) {
      console.log("[review:push] пустой diff — пропускаю реф");
      continue;
    }
    try {
      const result = await service.review({
        source: `push ${range}`,
        title: ref.localRef,
        files,
        diff,
      });
      const artifact = await saveReviewArtifact(result);
      printReview(result, artifact);
      if (result.verdict !== "approved") approved = false;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`[review:push] сбой ревью: ${message}`);
      approved = false; // strict: нет ревью → нет approve → блок
    }
  }

if (!approved) {
    console.error("\n[review:push] 🚫 ПУШ ЗАБЛОКИРОВАН — ревью не аппрувнуло изменения.");
    console.error("[review:push] Обход (осознанно): REVIEW_SKIP=1 git push … или git push --no-verify");
    return 1;
  }
  console.log("\n[review:push] ✅ ревью approved — пуш продолжается");
  return 0;
}

