  );
}

import type { ToolSpec } from "../deepseek.js";
import type { RagAnswerService, RagAskQuote, RagAskSource } from "../rag/answer.js";

/**
 * Day25 (design D-2, 02-F-7 → 04-F-11): локальная тулза `rag_ask` — KISS-модуль
 * без реестра провайдеров. Конвейер дня 24 не вскрывается: dispatch зовёт
 * RagAnswerService.ask() как библиотеку в том же процессе (Q-a). В контекст
 * модели уходит компакт-рендер <4000 симв. — ТОЛЬКО ФАКТЫ (TOOL_RESULTS_POLICY,
 * llm-agent.ts:640–643: данные, а не инструкции); полный payload — в
 * tool.calls[].payload для UI/трассы.
 */

export const RAG_TOOL_NAME = "rag_ask";

/** Канон дня 24: structured + k=12 (замер 30.09 — лучший ответ-уровень). */
const RAG_K = 12;
/** 04-F-5: кап вопроса ~2k симв. — защита 3k-токенного бюджета ask(). */
const RAG_QUESTION_CHAR_CAP = 2_000;
/** 04-F-5: клип clipToolThread (4000) не должен отрезать список источников. */
const RAG_RENDER_CHAR_CAP = 4_000;
/** D-2: локальный dispatch держит внутренние 60 с — не через 90-с callMcpTool. */
const RAG_TOOL_TIMEOUT_MS = 60_000;
/** Компакт-рендер: answer ~1200–1500, топ-2–3 цитаты (04-F-5). */
const RENDER_ANSWER_CHAR_CAP = 1_500;
const RENDER_QUOTE_CHAR_CAP = 220;
const RENDER_QUOTES_COUNT = 3;

export function buildRagToolSpec(): ToolSpec {
  return {
    type: "function",
    function: {
      name: RAG_TOOL_NAME,
      description:
        "Поиск по базе знаний Trigger Helper (триггерные точки, техники самопомощи). " +
        "Вернёт ответ по базе, цитаты и список источников [source › section] либо " +
        "dontKnow=true, если релевантного ничего нет. Вопрос формулируй самодостаточно " +
        "(с учётом истории диалога), на русском, до 2000 символов.",
      parameters: {
        type: "object",
        properties: {
          question: {
            type: "string",
            description: "Самодостаточный вопрос по базе знаний (мышца, симптом, техника).",
          },
        },
        required: ["question"],
      },
    },
  };
}

/** Метка источника — тот же формат, что требует рельса в тексте ответа (D-3). */
export function ragSourceLabel(s: { source: string; section: string }): string {
  return `[${s.source} › ${s.section || "—"}]`;
}

/** Метка источника — тот же формат, что требует рельса в тексте ответа (D-3). */
export function ragSourceLabel(s: { source: string; section: string }): string {
  return `[${s.source} › ${s.section || "—"}]`;
}

/** Полный payload тулзы — UI-карточка и трасса (02b-F-3, аддитивно). */
export type RagToolPayload = {
  question: string;
  answer: string;
  quotes: RagAskQuote[];
  sources: RagAskSource[];
  /** Метки [source › section] для всех источников (детекция рельсы + UI). */
  labels: string[];
  dontKnow: boolean;
  topCosine: number | null;
  /** Порог dontKnow-гейта (tune-артефакт; отсутствует = гейт выключен). */
  threshold?: number | null;
  /** Средние стадии пайплайна (Костя 041004: «больше шагов в трейсе»):
   *  рерайт / ранжирование / верификация — аддитивно из result.meta. */
  rewrite?: { variants: string[]; tokens: number; latencyMs: number; fallback: boolean } | null;
  poolRanked?: number | null;
  keptAfterFilter?: number | null;
  injectedCount?: number | null;
  quotesValid?: number | null;
  quotesSource?: "model" | "server_fallback" | null;
  usage?: unknown;
  latencyMs?: number;
  /** ok:false-исход: причина ошибки вместо данных. */
  error?: string;
};

export type RagToolOutcome = {
  ok: boolean;
  /** Компактный модель-ориентированный рендер (факты, ≤4000 симв.). */
  content: string;
  /** Полный payload для trace/UI. */
  payload: RagToolPayload;
};

export type RagToolOutcome = {
  ok: boolean;
  /** Компактный модель-ориентированный рендер (факты, ≤4000 симв.). */
  content: string;
  /** Полный payload для trace/UI. */
  payload: RagToolPayload;
};

/** Компакт-рендер в контекст модели: только факты, без повелений (04-F-4). */
export function renderRagToolResult(p: RagToolPayload): string {
  const lines: string[] = [
    `rag_ask · dontKnow=${p.dontKnow ? "true" : "false"}` +
      (p.topCosine != null ? ` · topCosine=${p.topCosine}` : ""),
  ];
  if (p.error) {
    lines.push(`ошибка вызова: ${p.error}`);
    return lines.join("\n").slice(0, RAG_RENDER_CHAR_CAP);
  }
  const answer =
    p.answer.length > RENDER_ANSWER_CHAR_CAP
      ? `${p.answer.slice(0, RENDER_ANSWER_CHAR_CAP - 1)}…`
      : p.answer;
  lines.push(`Ответ по базе: ${answer}`);
  if (!p.dontKnow) {
    const quotes = p.quotes.slice(0, RENDER_QUOTES_COUNT);
    if (quotes.length > 0) {
      lines.push("Цитаты:");
      for (const q of quotes) {
        const text =
          q.quote.length > RENDER_QUOTE_CHAR_CAP
            ? `${q.quote.slice(0, RENDER_QUOTE_CHAR_CAP - 1)}…`
            : q.quote;
        // Корпус v2 (D-5): атрибуция доезжает и в контекст модели —
        // маркированная цитата с автором/книгой, факт-проза с пометкой «по:».
        const who = q.author && q.book ? `${q.author}, «${q.book}»` : "";
        const mark = q.paraphrase === true ? "по: " : "";
        lines.push(`- «${text}»${who ? ` — ${who}` : ""} — ${mark}${q.source} › ${q.section || "—"}`);
      }
    }
    if (p.labels.length > 0) {
      lines.push("Источники:");
      for (const label of p.labels) lines.push(`- ${label}`);
    }
  }
  const text = lines.join("\n");
  return text.length > RAG_RENDER_CHAR_CAP
    ? `${text.slice(0, RAG_RENDER_CHAR_CAP - 1)}…`
    : text;
}

function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`rag_ask timeout (${ms} мс)`)), ms);
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

/**
 * Dispatch локальной тулзы: ask({mode:"rag", strategy:"structured", k:12}),
 * внутренний кап 60 с. Кидать не должен — ошибки становятся ok:false-исходом
 * (транспорт/таймаут ≠ isError-результат, тот же деградационный контракт).
 */
export async function dispatchRagAsk(
  args: Record<string, unknown>,
  ragAnswer: RagAnswerService,
  /** Прогресс средних стадий в живой трейс (Костя 041004). */
  onStage?: (stage: string, text: string) => void,
): Promise<RagToolOutcome> {
  const question =
    typeof args.question === "string" ? args.question.trim().slice(0, RAG_QUESTION_CHAR_CAP) : "";
  if (!question) {
    const payload: RagToolPayload = {
      question: "",
      answer: "",
      quotes: [],
      sources: [],
      labels: [],
      dontKnow: false,
      topCosine: null,
      error: "invalid_question",
    };
    return { ok: false, content: JSON.stringify({ error: "invalid_question" }), payload };
  }
  try {
    // Костя 04.10: первое разговорное «болит голова» ловило dontKnow-гейт
    // (косинус разговорной формулировки против клинической базы < порога),
    // повторный вопрос с уточнением — уже нет. rewrite=true: рерайтер дня 23
    // переформулирует в варианты, гейт ранжирует объединение (per-chunk max)
    // — клинический вариант поднимает top-1 выше порога. Фолбэк безопасен.

const result = await withTimeout(
      ragAnswer.ask({ q: question, mode: "rag", strategy: "structured", k: RAG_K, rewrite: true, onStage }),
      RAG_TOOL_TIMEOUT_MS,
    );
    const payload: RagToolPayload = {
      question,
      answer: result.answer,
      quotes: result.quotes,
      sources: result.sources,
      labels: result.sources.map((s) => ragSourceLabel(s)),
    dontKnow: result.meta.dontKnow === true,
    topCosine: result.meta.topCosine ?? null,
    threshold: result.meta.threshold ?? null,
      // Средние стадии (мета дня 23/24 — прокидываем в payload для трейса)
      rewrite: result.meta.rewrite
        ? {
            variants: result.meta.rewrite.variants,
            tokens: result.meta.rewrite.tokens,
            latencyMs: result.meta.rewrite.latencyMs,
            fallback: result.meta.rewrite.fallback,
          }
        : null,
      poolRanked: result.meta.poolRanked ?? null,
      keptAfterFilter: result.meta.keptAfterFilter ?? null,
      injectedCount: result.meta.injectedCount ?? null,
      quotesValid: result.meta.quotesValid ?? null,
      quotesSource: result.meta.quotes_source ?? null,
      usage: result.usage,
      latencyMs: result.meta.latencyMs,
    };
    return { ok: true, content: renderRagToolResult(payload), payload };
  } catch (error) {
    const message = error instanceof Error ?

error.message : String(error);
    const payload: RagToolPayload = {
      question,
      answer: "",
      quotes: [],
      sources: [],
      labels: [],
      dontKnow: false,
      topCosine: null,
      error: message,
    };
    return { ok: false, content: JSON.stringify({ error: message }), payload };
  }
}

import type { AgentMessage } from "@trigger-helper/shared";
import { costRubFromUsage } from "../pricing.js";

/**
 * Day08 — token estimation.
 *
 * API usage is the source of truth for what was billed. Estimation is needed
 * where usage cannot answer:
 *  1. the size of the whole thread when only a tail is sent,
 *  2. a pre-flight decision before spending a request,
 *  3. the system / history / user split.
 *
 * Heuristic: Cyrillic ≈ 2.5 chars per token, Latin/code/JSON ≈ 4. Values are
 * approximate by design — the UI shows «оценка» next to the API fact.
 */

/** OpenAI-compatible chat format overhead per message. */
export const MESSAGE_OVERHEAD_TOKENS = 4;

const CYRILLIC = /[\u0400-\u04FF]/;

export type EstimateMessage = { role: string; content: string };

export function estimateTokens(text: string): number {
  if (!text) return 0;
  let cyrillic = 0;
  let other = 0;
  for (const ch of text) {
    if (CYRILLIC.test(ch)) cyrillic += 1;
    else other += 1;
  }
  return Math.ceil(cyrillic / 2.5 + other / 4);
}

export function estimateMessageTokens(message: EstimateMessage): number {
  return estimateTokens(message.content) + MESSAGE_OVERHEAD_TOKENS;
}

export function estimateChatTokens(messages: EstimateMessage[]): number {
  return messages.reduce((sum, m) => sum + estimateMessageTokens(m), 0);
}

/** Request size split — «сколько стоит системный промпт / история / ввод». */
export type TokenBreakdown = {
  system: number;
  history: number;
  user: number;
  total: number;
  historyMessages: number;
  /** Day10: extract usage when folded into the run estimate. */
  extract?: number;
  /** Day17: tool-schema tokens riding every tools-run request. */
  tools?: number;
};

export function estimateMessagesBreakdown(parts: {
  system: string;
  history: EstimateMessage[];
  user: string;
}): TokenBreakdown {
  const system = estimateTokens(parts.system) + MESSAGE_OVERHEAD_TOKENS;
  const history = parts.history.reduce(
    (sum, m) => sum + estimateMessageTokens(m),
    0,
  );
  const user = estimateTokens(parts.user) + MESSAGE_OVERHEAD_TOKENS;
  return {
    system,
    history,
    user,
    total: system + history + user,
    historyMessages: parts.history.length,
  };
}

/** Whole-thread stats: estimation over all messages + actual usage facts. */
export type ThreadTokens = {
  count: number;
  tokensEstimate: number;
  /** Sum of usage.total_tokens from assistant messages (API fact). */
  tokensActualSum: number;
  costRubSum: number;
  /** Day08: total tokens saved by compressions in this thread. */
  savedTokensSum: number;
};

export function sumThreadTokens(messages: AgentMessage[]): ThreadTokens {
  let tokensEstimate = 0;
  let tokensActualSum = 0;
  let costRubSum = 0;
  let savedTokensSum = 0;

for (const m of messages) {
    tokensEstimate += estimateMessageTokens(m);
    if (m.usage) {
      tokensActualSum += m.usage.total_tokens;
    }
    costRubSum += messageCostRub(m);
    savedTokensSum += m.saved_tokens ?? 0;
  }

return {
    count: messages.length,
    tokensEstimate,
    tokensActualSum,
    costRubSum: Number(costRubSum.toFixed(4)),
    savedTokensSum,
  };
}

/** Billed ₽ for one message: stored display value, else derived from usage. */
export function messageCostRub(message: AgentMessage): number {
  if (message.cost_rub !== undefined) return message.cost_rub;
  return message.usage ? costRubFromUsage(message.usage) : 0;
}

import type { FastifyReply } from "fastify";
import type { Env } from "../config/env.js";
import type { UsageLedgerService } from "./usage-ledger.js";
import { todayMoscowDate } from "./model-cost-tier.js";

const MSK_DAY_MS = 86_400_000;
const EPS_FRAC = 1 / 1_440; // ~1 minute

export type BudgetSnapshot = {
  day: string;
  used_rub: number;
  limit_rub: number;
  remaining_rub: number | null;
  expensive_used_rub: number;
  expensive_limit_rub: number;
  delay_ms: number;
  elapsed_frac: number;
  rejected: boolean;
  reason?: string;
};

function moscowElapsedFrac(now = new Date()): number {
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Europe/Moscow",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(now);
  const get = (type: string) =>
    Number(parts.find((p) => p.type === type)?.value ?? 0);
  const ms =
    ((get("hour") * 60 + get("minute")) * 60 + get("second")) * 1000;
  return Math.min(1, Math.max(0, ms / MSK_DAY_MS));
}

/** fill^α + ahead^β — see docs/reviews/260908-cost-aware-throttle.md */
export function computeDelayMs(
  spent: number,
  budget: number,
  elapsedFrac: number,
  env: Pick<
    Env,
    | "BUDGET_DELAY_ALPHA"
    | "BUDGET_DELAY_BETA"
    | "BUDGET_DELAY_FILL_MS"
    | "BUDGET_DELAY_PACE_MS"
    | "BUDGET_DELAY_MAX_MS"
  >,
): number {
  if (budget <= 0) return 0;
  const u = Math.min(1, Math.max(0, spent / budget));
  const e = Math.max(elapsedFrac, EPS_FRAC);
  const pace = u / e;
  const fill = u ** env.BUDGET_DELAY_ALPHA;
  const ahead = Math.max(0, pace - 1) ** env.BUDGET_DELAY_BETA;
  const raw =
    env.BUDGET_DELAY_FILL_MS * fill + env.BUDGET_DELAY_PACE_MS * ahead;
  return Math.min(env.BUDGET_DELAY_MAX_MS, Math.round(raw));
}

export async function getBudgetSnapshot(
  ledger: UsageLedgerService,
  env: Env,
  now = new Date(),
): Promise<BudgetSnapshot> {
  const totals = await ledger.getTotals();
  const day = totals.budget_day ?? totals.expensive_day ?? todayMoscowDate();
  const used = totals.cost_rub_today ?? 0;
  const expUsed = totals.cost_rub_expensive_today ?? 0;
  const limit = env.DAILY_BUDGET_RUB;
  const expLimit = env.DAILY_BUDGET_EXPENSIVE_RUB;
  const elapsed = moscowElapsedFrac(now);

if (limit <= 0) {
    return {
      day,
      used_rub: used,
      limit_rub: 0,
      remaining_rub: null,
      expensive_used_rub: expUsed,
      expensive_limit_rub: expLimit,
      delay_ms: 0,
      elapsed_frac: elapsed,
      rejected: false,
    };
  }

if (used >= limit) {
    return {
      day,
      used_rub: used,
      limit_rub: limit,
      remaining_rub: 0,
      expensive_used_rub: expUsed,
      expensive_limit_rub: expLimit,
      delay_ms: 0,
      elapsed_frac: elapsed,
      rejected: true,
      reason: "daily_budget_rub",
    };
  }

if (expLimit > 0 && expUsed >= expLimit) {
    return {
      day,
      used_rub: used,
      limit_rub: limit,
      remaining_rub: Number((limit - used).toFixed(4)),
      expensive_used_rub: expUsed,
      expensive_limit_rub: expLimit,
      delay_ms: 0,
      elapsed_frac: elapsed,
      rejected: true,
      reason: "daily_budget_expensive_rub",
    };
  }

const delayTotal = computeDelayMs(used, limit, elapsed, env);
  const delayExp =
    expLimit > 0 ? computeDelayMs(expUsed, expLimit, elapsed, env) : 0;
  const delay_ms = Math.max(delayTotal, delayExp);

const delayTotal = computeDelayMs(used, limit, elapsed, env);
  const delayExp =
    expLimit > 0 ? computeDelayMs(expUsed, expLimit, elapsed, env) : 0;
  const delay_ms = Math.max(delayTotal, delayExp);

return {
    day,
    used_rub: used,
    limit_rub: limit,
    remaining_rub: Number((limit - used).toFixed(4)),
    expensive_used_rub: expUsed,
    expensive_limit_rub: expLimit,
    delay_ms,
    elapsed_frac: Number(elapsed.toFixed(4)),
    rejected: false,
  };
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Hard 429 at budget ceiling; else optional delay before LLM.
 * Sets x-budget-* headers when delay > 0 or rejected.
 */
export async function applyCostAwareThrottle(
  reply: FastifyReply,
  snapshot: BudgetSnapshot,
): Promise<"ok" | "rejected"> {
  reply.header("x-budget-used-rub", String(snapshot.used_rub));
  reply.header("x-budget-limit-rub", String(snapshot.limit_rub));
  reply.header("x-budget-delay-ms", String(snapshot.delay_ms));

if (snapshot.rejected) {
    reply.status(429).send({
      error: "Budget limit reached",
      message:
        snapshot.reason === "daily_budget_expensive_rub"
          ? `Дневной бюджет дорогих моделей: ₽${snapshot.expensive_limit_rub} (МСК).`
          : `Дневной бюджет: ₽${snapshot.limit_rub} (МСК).`,
      budget: snapshot,
    });
    return "rejected";
  }

if (snapshot.delay_ms > 0) {
    await sleep(snapshot.delay_ms);
  }
  return "ok";
}

