const release1 = await gate.acquire();
    events.push("a-in");
    expect(gate.snapshot()).toEqual({ inflight: 1, waiting: 0, max: 1 });

let release2: (() => void) | undefined;
    const p2 = gate
      .acquire((pos) => {
