      });

await Promise.resolve();
    expect(queuedPos).toBe(1);
    expect(gate.snapshot()).toEqual({ inflight: 1, waiting: 1, max: 1 });
    expect(events).toEqual(["a-in", "b-queued:1"]);

release1();
    await p2;
