export function localLlmTuning(model: string): LocalLlmTuning {
  return (
    LOCAL_LLM_CATALOG.find((entry) => entry.id === model)?.tuning ?? {
      numCtx: 2048,
      ragPromptTokenBudget: 1000,
    }
  );
}

