server.registerTool(
    "list_points",
    {
      description: OWN_MCP_TOOL_SCHEMAS[0].description,
      inputSchema: listPointsShape,
    },
    async ({ zone }) => {
      return toolText(await listPointCards(zone));
    },
  );

server.registerTool(
    "get_point",
    {
      description: OWN_MCP_TOOL_SCHEMAS[1].description,
      inputSchema: getPointShape,
