import fs from "node:fs/promises";
import { glob } from "node:fs/promises";
import path from "node:path";
import type { CorpusFile } from "./corpus.js";
import { repoRoot } from "./paths.js";

/**
 * Day31 project RAG corpus (design D-31-5/12): README + STACK + shared schemas.
 * Day32 (гейт 261013, Pick D): + код сервера и клиента — «документация + код»
 * для AI-ревью; chunking остаётся существующий structured (адаптация чанков
 * под код — вне дня, честно в NOTES).
 */

const CORPUS_README = "README.md";
const CORPUS_STACK = "docs/STACK.md";
const SCHEMAS_DIR = "shared/src/schemas";
const CODE_DIRS: Array<{ dir: string; ext: string }> = [
  { dir: "server/src", ext: ".ts" },
  { dir: "client/src", ext: ".ts" },
  { dir: "client/src", ext: ".svelte" },
];

function normalizeText(raw: string): string {
  return raw
    .replace(/\r\n?/g, "\n")
    .replace(/[\u200B\u200C\u200D\uFEFF]/g, "")
    .trimEnd();
}

function firstH1(text: string): string | undefined {
  const line = text.split("\n").find((l) => l.startsWith("# ") && l.slice(2).trim().length > 0);
  return line ? line.slice(2).trim() : undefined;
}

async function exists(p: string): Promise<boolean> {
  try {
    await fs.access(p);
    return true;
  } catch {
    return false;
  }
}

export class ProjectCorpusReader {
  constructor(private readonly root: string = repoRoot) {}

async function exists(p: string): Promise<boolean> {
  try {
    await fs.access(p);
    return true;
  } catch {
    return false;
  }
}

async listSources(): Promise<string[]> {
    const sources: string[] = [];
    for (const fixed of [CORPUS_README, CORPUS_STACK]) {
      if (await exists(path.join(this.root, fixed))) sources.push(fixed);
    }
    const schemaDir = path.join(this.root, SCHEMAS_DIR);
    if (await exists(schemaDir)) {
      for await (const rel of glob("**/*.ts", { cwd: schemaDir })) {
        sources.push(path.posix.join(SCHEMAS_DIR, rel.split(path.sep).join("/")));
      }
    }
    for (const { dir, ext } of CODE_DIRS) {
      const abs = path.join(this.root, dir);
      if (!(await exists(abs))) continue;
      for await (const rel of glob(`**/*${ext}`, { cwd: abs })) {
        sources.push(path.posix.join(dir, rel.split(path.sep).join("/")));
      }
    }
    sources.sort();
    return sources;
  }

async readAll(): Promise<CorpusFile[]> {
    const sources = await this.listSources();
    const files: CorpusFile[] = [];
    for (const source of sources) {
      const raw = await fs.readFile(path.join(this.root, source), "utf8");
      const text = normalizeText(raw);
      if (!text.trim()) {
        console.log(`[rag/project-corpus] skip empty file: ${source}`);
        continue;
      }
      const isMarkdown = source.endsWith(".md");
      files.push({
        source,
        file: path.basename(source),
        title: isMarkdown ? (firstH1(text) ?? path.basename(source)) : path.basename(source),
        text,
      });
    }
    return files;
  }
}

export function createProjectCorpusReader(root?: string): ProjectCorpusReader {
  return new ProjectCorpusReader(root);
}

import path from "node:path";
import type { Env } from "../../config/env.js";
import type { ToolSpec } from "../deepseek.js";
import { ragSourceLabel, type RagToolPayload } from "../agent/rag-tool.js";
import type { RagAskSource } from "./answer.js";
import { repoRoot } from "./paths.js";
import { createRagService, type RagChunk, type SearchHit } from "./store.js";

/**
 * Day31 (design D-31-19): retrieve-only search over data/project-rag structured index.
 */

export const PROJECT_SEARCH_TOOL = "project_search";

const PROJECT_K = 8;
const RENDER_CHAR_CAP = 4_000;
const SNIPPET_CHAR_CAP = 320;
const SNIPPET_COUNT = 5;

export type ProjectSearcher = {
  search(query: string): Promise<{ chunks: RagChunk[]; sources: RagAskSource[]; topCosine: number | null }>;
};

function hitsToSources(hits: SearchHit[]): RagAskSource[] {
  return hits.map(({ chunk, score }) => ({
    chunk_id: chunk.chunk_id,
    score,
    source: chunk.source,
    file: chunk.file,
    title: chunk.title,
    section: chunk.section,
  }));
}

export function createProjectSearch(env: Env): ProjectSearcher {
  const projectEnv: Env = {
    ...env,
    RAG_INDEX_DIR: path.join(repoRoot, "data/project-rag"),
  };
  const rag = createRagService(projectEnv);

return {
    async search(query: string) {
      const q = query.trim();
      if (!q) return { chunks: [], sources: [], topCosine: null };
      const { hits } = await rag.search(q, "structured", PROJECT_K);
      const topCosine = hits[0]?.score ?? null;
      if (topCosine != null) {
        console.log(`[project_search] topCosine=${topCosine.toFixed(4)} query=${JSON.stringify(q.slice(0, 80))}`);
      }
      return {
        chunks: hits.map((h) => h.chunk),
        sources: hitsToSources(hits),
        topCosine,
      };
    },
  };
}

export function buildProjectSearchToolSpec(): ToolSpec {
  return {
    type: "function",
    function: {
      name: PROJECT_SEARCH_TOOL,
      description:
        "Поиск по документации проекта Trigger Helper (README, STACK, схемы shared). " +
        "Вернёт фрагменты и список источников [source › section] без LLM-ответа. " +
        "Запрос формулируй самодостаточно, на русском.",
      parameters: {
        type: "object",
        properties: {
          query: {
            type: "string",
            description: "Вопрос по структуре проекта, стеку, схемам данных.",
          },
        },
        required: ["query"],
      },
    },
  };
}

export type ProjectSearchToolPayload = Pick<
  RagToolPayload,
  "question" | "answer" | "quotes" | "sources" | "labels" | "dontKnow" | "topCosine" | "error"
>;

export type ProjectSearchOutcome = {
  ok: boolean;
  content: string;
  payload: ProjectSearchToolPayload;
};

export type ProjectSearchToolPayload = Pick<
  RagToolPayload,
  "question" | "answer" | "quotes" | "sources" | "labels" | "dontKnow" | "topCosine" | "error"
>;

function renderProjectSearch(payload: ProjectSearchToolPayload): string {
  const lines: string[] = [
    `project_search · dontKnow=${payload.dontKnow ? "true" : "false"}` +
      (payload.topCosine != null ? ` · topCosine=${payload.topCosine.toFixed(4)}` : ""),
  ];
  if (payload.error) {
    lines.push(`ошибка: ${payload.error}`);
    return lines.slice(0, RENDER_CHAR_CAP).join("\n");
  }
  if (payload.sources.length === 0) {
    lines.push("Фрагментов не найдено.");
    return lines.join("\n");
  }
  lines.push("Фрагменты:");
  for (const q of payload.quotes.slice(0, SNIPPET_COUNT)) {
    lines.push(`- ${q.quote} — ${q.source} › ${q.section || "—"}`);
  }
  if (payload.labels.length > 0) {
    lines.push("Источники:");
    for (const label of payload.labels) lines.push(`- ${label}`);
  }
  const text = lines.join("\n");
  return text.length > RENDER_CHAR_CAP ? `${text.slice(0, RENDER_CHAR_CAP - 1)}…` : text;
}

export async function runProjectSearch(
  query: string,
  searcher: ProjectSearcher,
): Promise<ProjectSearchOutcome> {
  const question = query.trim();
  if (!question) {
    const payload: ProjectSearchToolPayload = {
      question: "",
      answer: "",
      quotes: [],
      sources: [],
      labels: [],
      dontKnow: false,
      topCosine: null,
      error: "invalid_query",
    };
    return { ok: false, content: renderProjectSearch(payload), payload };
  }
  try {
    const { chunks, sources, topCosine } = await searcher.search(question);
    const quotes = chunks.slice(0, SNIPPET_COUNT).map((c) => {
      const snippet =
        c.text.length > SNIPPET_CHAR_CAP ? `${c.text.slice(0, SNIPPET_CHAR_CAP - 1)}…` : c.text;
      return {
        quote: snippet.replace(/\s+/g, " ").trim(),
        chunk_id: c.chunk_id,
        source: c.source,
        section: c.section,
      };
    });
    const payload: ProjectSearchToolPayload = {
      question,
      answer: "",
      quotes,
      sources,
      labels: sources.map((s) => ragSourceLabel(s)),
      dontKnow: false,
      topCosine,
    };
    return { ok: true, content: renderProjectSearch(payload), payload };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const payload: ProjectSearchToolPayload = {
      question,
      answer: "",
      quotes: [],
      sources: [],
      labels: [],
      dontKnow: false,
      topCosine: null,
      error: message,
    };
    return { ok: false, content: renderProjectSearch(payload), payload };
  }
}

const RERANK_MODEL = "BGLAW/bge-reranker-v2-m3-onnx-defaulttask";
const BATCH_SIZE = 8;
const MAX_LENGTH = 512; // v2-m3 max_position_embeddings=8194 → truncate explicitly

const tuneArtifactSchema = z.object({
  pool: z.number().int().min(1).max(220),
  threshold: z
    .object({
      value: z.number().min(0).max(1),
      /** "absolute-sigmoid" | "relative-margin" (D-3 ladder rung 2). */
      kind: z.string().min(1),
    })
    .passthrough(),
});

type TuneArtifact = z.infer<typeof tuneArtifactSchema>;

interface TensorLike {
  tolist(): number[][];
}

interface TokenizerLike {
  (texts: string[], options: {
    text_pair?: string[];
    padding?: boolean;
    truncation?: boolean;
    max_length?: number;
  }): Promise<unknown>;
}

interface ModelLike {
  (inputs: unknown): Promise<{ logits: TensorLike }>;
}

interface TransformersModule {
  AutoTokenizer: { from_pretrained(model: string): Promise<TokenizerLike> };
  AutoModelForSequenceClassification: {
    from_pretrained(model: string, options: { dtype: string }): Promise<ModelLike>;
  };
  env: { cacheDir: string };
}

let transformersPromise: Promise<TransformersModule> | null = null;

async function loadTransformers(env: Env): Promise<TransformersModule> {
  if (!transformersPromise) {
    transformersPromise = (async () => {
      const mod = (await import("@huggingface/transformers")) as unknown as TransformersModule;
      // Same cache as the day-21 embedder (var/ is gitignored and never
      // deployed — the VPS pays the download on the first request, D-11).
      const cacheDir = resolveFromRoot(env.RAG_CACHE_DIR, "var/hf-cache");
      await fs.mkdir(cacheDir, { recursive: true });
      mod.env.cacheDir = cacheDir;
      return mod;
    })();
  }
  return transformersPromise;
}

function sigmoid(x: number): number {
  return 1 / (1 + Math.exp(-x));
}

function round4(n: number): number {
  return Math.round(n * 10_000) / 10_000;
}

/** Model-only scorer — no tune artifact needed (rag:tune itself uses this to
 *  CREATE the artifact). Lazy load: boot never touches the model. */
export interface RerankScorer {
  readonly model: string;
  /** Sigmoid relevance 0..1 of query against each text, in input order. */
  scoreAll(query: string, texts: string[]): Promise<number[]>;
}

export async function createRerankScorer(env: Env): Promise<RerankScorer> {
  let pending: Promise<{ tokenizer: TokenizerLike; model: ModelLike }> | null = null;

const load = (): Promise<{ tokenizer: TokenizerLike; model: ModelLike }> => {
    if (!pending) {
      pending = (async () => {
        try {
          const mod = await loadTransformers(env);
          const tokenizer = await mod.AutoTokenizer.from_pretrained(RERANK_MODEL);
          const model = await mod.AutoModelForSequenceClassification.from_pretrained(RERANK_MODEL, {
            dtype: "q8",
          });
          return { tokenizer, model };
        } catch (err) {
          pending = null; // house pending-promise pattern: failed load → retry next call
          throw new RagUnavailableError(
            `reranker load failed for ${RERANK_MODEL}: ${err instanceof Error ? err.message : String(err)}`,
          );
        }
      })();
    }
    return pending;
  };

return {
    model: RERANK_MODEL,
    async scoreAll(query: string, texts: string[]): Promise<number[]> {
      if (texts.length === 0) return [];
      const { tokenizer, model } = await load();
      const scores: number[] = [];
      for (let offset = 0; offset < texts.length; offset += BATCH_SIZE) {
        const batch = texts.slice(offset, offset + BATCH_SIZE);
        // Cross-encoder pair (query, doc): transformers.js requires text and
        // text_pair arrays of the SAME length → repeat the query per doc.
        const inputs = await tokenizer(
          batch.map(() => query),
          {
            text_pair: batch,
            padding: true,
            truncation: true,
            max_length: MAX_LENGTH,
          },
        );
        const out = await model(inputs);
        const logits = out.logits.tolist(); // [batch, 1]
        for (const row of logits) scores.push(sigmoid(row[0] ?? 0));
      }
      return scores;
    },
  };
}

export interface RerankResult {
  /** Filtered + re-sorted by the reranker's sigmoid (score replaced, round4 —
   *  D-5: sources[].score is always the score the list is sorted by). */
  hits: SearchHit[];
  /** Hits after the threshold cut, before the k_final slice (D-3/F-5). */
  kept: number;
  latencyMs: number;
  pool: number;
  threshold: number;
}

export interface Reranker {
  readonly model: string;
  /** Ask-pipeline precheck (F-04-2): loads model + tune artifact BEFORE any
   * rewrite spend; failure → RagUnavailableError → mode-scoped 503. */
  ensureReady(): Promise<void>;
  /** Second stage: top-pool → cross-encoder scores → threshold cut → re-sort.
   * Anti-regression guard: the post-rerank rank-1 never drops (D-3). */
  rerank(query: string, hits: SearchHit[]): Promise<RerankResult>;
  /** Хвост дня 29 (11.10): размер пула из артефакта — для ЧЕСТНОЙ фазы
   * «Уточняю релевантность N фрагментов…» (local-llm раньше показывала весь
   * косинус-пул 262, а кросс-энкодер читает только топ-pool). Читает ТОЛЬКО
   * артефакт, БЕЗ загрузки модели — фаза не должна ждать холодный старт
   * ONNX-сессии; null = реранкер выключен/артефакт бит (base-деградация). */
  rerankPoolSize(): Promise<number | null>;
}

export function createReranker(env: Env): Reranker {
  // D-11 hardening (OOM measured 01.10): the host can switch the reranker off
  // — rerank/full arms then 503 cleanly BEFORE any model load instead of the
  // whole process being OOM-killed mid-request. Nothing eager is created when
  // disabled (an eagerly-rejected promise would crash boot as unhandled).
  const disabled =
    env.RAG_RERANK_ENABLED === "0" || (env.RAG_RERANK_ENABLED ?? "").toLowerCase() === "false";
  let scorerPromise: Promise<RerankScorer> | null = null;
  let artifactPending: Promise<{ scorer: RerankScorer; artifact: TuneArtifact }> | null = null;

const ensureReady = (): Promise<{ scorer: RerankScorer; artifact: TuneArtifact }> => {
    if (disabled) {
      return Promise.reject(
        new RagUnavailableError(
          "reranker disabled on this host (RAG_RERANK_ENABLED=0) — база/rewrite работают, полный этап считается локально",
        ),
      );
    }
    if (!artifactPending) {
      artifactPending = (async () => {
        try {
          if (!scorerPromise) scorerPromise = createRerankScorer(env);
          const scorer = await scorerPromise;
          const artifactPath = path.join(repoRoot, "data", "rag", "tune-rerank.json");
          let raw: string;
          try {
            raw = await fs.readFile(artifactPath, "utf8");
          } catch {
            throw new RagUnavailableError(
              "tune artifact missing: data/rag/tune-rerank.json — run npm run rag:tune (design D-3)",
            );
          }
          let parsedJson: unknown;
          try {
            parsedJson = JSON.parse(raw);
          } catch {
            throw new RagUnavailableError("tune artifact corrupt (JSON.parse)");
          }
          const parsed = tuneArtifactSchema.safeParse(parsedJson);
          if (!parsed.success) {
            throw new RagUnavailableError(`tune artifact schema mismatch: ${parsed.error.message}`);
          }
          return { scorer, artifact: parsed.data };
        } catch (err) {
          artifactPending = null; // failed artifact load → retry on next call
          throw err;
        }
      })();
    }
    return artifactPending;
  };

return {
    model: RERANK_MODEL,
    ensureReady(): Promise<void> {
      return ensureReady().then(() => undefined);
    },
    async rerankPoolSize(): Promise<number | null> {
      if (disabled) return null;
      try {
        const raw = await fs.readFile(
          path.join(repoRoot, "data", "rag", "tune-rerank.json"),
          "utf8",
        );
        const parsed = tuneArtifactSchema.safeParse(JSON.parse(raw));
        return parsed.success ? parsed.data.pool : null;
      } catch {
        return null;
      }
    },
    async rerank(query: string, hits: SearchHit[]): Promise<RerankResult> {
      const { scorer, artifact } = await ensureReady();
      const pool = Math.min(artifact.pool, hits.length);
      const top = hits.slice(0, pool);
      const t0 = Date.now();
      const scores = await scorer.scoreAll(query, top.map((h) => h.chunk.text));
      const latencyMs = Date.now() - t0;
      const scored = top
        .map((hit, i) => ({ hit, score: scores[i] ?? 0 }))
        .sort((a, b) => b.score - a.score);
      // D-3 threshold ladder: "absolute-sigmoid" (score ≥ value) or
      // "relative-margin" (score ≥ top1 − value — per-query scale varies
      // wildly, tune 30.09/01.10 measured no global gap → rung 2).
      const top1 = scored.length ? scored[0].score : 0;
      const kind = artifact.threshold.kind;
      const cutoff =
        kind === "relative-margin" ?

top1 - artifact.threshold.value : artifact.threshold.value;
      const keptList = scored.filter((s) => s.score >= cutoff);
      if (keptList.length === 0 && scored.length > 0) {
        keptList.push(scored[0]); // D-3 guard: never drop the post-rerank rank-1
      }
      return {
        hits: keptList.map(({ hit, score }) => ({ chunk: hit.chunk, score: round4(score) })),
        kept: keptList.length,
        latencyMs,
        pool: artifact.pool,
        threshold: artifact.threshold.value,
      };
    },
  };
}

import { z } from "zod";
import type { LlmUsage } from "@trigger-helper/shared";
import type { ChatMessage, DeepSeekService } from "../deepseek.js";

/**
 * Day23 multi-query rewrite (design D-4): ONE deepseek-chat call (temp 0,
 * maxTokens 200, timeout 30 s) turns the reader's colloquial question into
 * 2–3 retrieval queries in corpus vocabulary (muscle names, symptom terms).
 *
 * OWN try/catch — this call never surfaces as 502 (answer.ts chat() rethrows,
 * the route maps that to 502; the rewrite must degrade instead, F-04-3): any
 * failure (timeout/5xx/parse) → fallback to the original question with
 * meta.rewrite = {fallback: true, error}.
 *
 * Red-team guard rails baked into the pipeline (answer.ts/store.ts): variants
 * feed RETRIEVAL only — the answer call keeps the original question; the union
 * with the original query is a per-chunk max in store.rankByQueries, so the
 * original can never be displaced.
 *
 * The prompt MUST contain the literal word "json" plus a format example —
 * DeepSeek JSON Output requirement (F-05-4): without it the API errors and
 * every call would silently fall back, making the matrix "prove" rewrite
 * useless for a wrong reason.
 */

const REWRITE_MODEL = "deepseek-chat";
const REWRITE_TEMPERATURE = 0;
const REWRITE_MAX_TOKENS = 200;
const REWRITE_TIMEOUT_MS = 30_000;
const MAX_VARIANTS = 3;

const REWRITE_MODEL = "deepseek-chat";
const REWRITE_TEMPERATURE = 0;
const REWRITE_MAX_TOKENS = 200;
const REWRITE_TIMEOUT_MS = 30_000;
const MAX_VARIANTS = 3;

const REWRITE_SYSTEM = [
  "Ты превращаешь вопрос читателя в поисковые запросы для базы знаний о триггерных точках (названия мышц по-русски и на латыни, симптомы, зоны отражённой боли).",
  'Дай 2–3 варианта короткого поискового запроса из словаря базы. Верни только json вида {"queries": ["запрос 1", "запрос 2"]} — без пояснений.',
].join("\n");

const queriesSchema = z.object({
  queries: z.array(z.string().trim().min(1)).min(1).max(5),
});

export interface RewriteResult {
  /** Variant queries only — the original question is always kept by the
   *  caller/store union (D-4 guard a: never replace, only add). */
  queries: string[];
  usage: LlmUsage | null;
  latencyMs: number;
  fallback: boolean;
  error?: string;
}

export interface QueryRewriter {
  rewriteQueries(q: string): Promise<RewriteResult>;
}

export interface QueryRewriter {
  rewriteQueries(q: string): Promise<RewriteResult>;
}

export function createRewriteQueries(deepSeek: DeepSeekService): QueryRewriter {
  return {
    async rewriteQueries(q: string): Promise<RewriteResult> {
      const t0 = Date.now();
      const messages: ChatMessage[] = [
        { role: "system", content: REWRITE_SYSTEM },
        { role: "user", content: q },
      ];
      try {
        const result = await deepSeek.chat(messages, {
          model: REWRITE_MODEL,
          temperature: REWRITE_TEMPERATURE,
          maxTokens: REWRITE_MAX_TOKENS,
          timeoutMs: REWRITE_TIMEOUT_MS,
          jsonMode: true,
        });
        // Lenient parse: the model may wrap JSON in code fences or prose.
        const match = result.reply.match(/\{[\s\S]*\}/);
        const parsed = queriesSchema.safeParse(JSON.parse(match ? match[0] : result.reply));
        if (!parsed.success) {
          return {
            queries: [],
            usage: result.usage,
            latencyMs: Date.now() - t0,
            fallback: true,
            error: "json parse failed",
          };
        }
        return {
          queries: parsed.data.queries.slice(0, MAX_VARIANTS),
          usage: result.usage,
          latencyMs: Date.now() - t0,
          fallback: false,
        };
      } catch (err) {
        return {
          queries: [],
          usage: null,
          latencyMs: Date.now() - t0,
          fallback: true,
          error: err instanceof Error ? err.message : String(err),
        };
      }
    },
  };
}

import fs from "node:fs/promises";
import path from "node:path";
import { z } from "zod";
import type { Env } from "../../config/env.js";
import { createEmbedder, type Embedder } from "./embeddings.js";
import { resolveFromRoot } from "./paths.js";

/**
 * Day21 store (design D-3/D-6, §3.1): JSON index load + validation, stats,
 * cosine search. Degrade-not-crash: any index problem (missing file, corrupt
 * JSON, schema mismatch, dim mismatch, embedder failure) is a
 * RagUnavailableError → routes answer 503 and the server lives on (day20 rule).
 *
 * Seam for days 22–25: search() returns FULL chunks (text + all metadata);
 * excerpt clipping is a route/UI concern only (pass 04, F-B).
 */

export const RAG_STRATEGIES = ["fixed", "structured"] as const;
export type RagStrategy = (typeof RAG_STRATEGIES)[number];

const chunkSchema = z.object({
  chunk_id: z.string().min(1),
  source: z.string().min(1),
  file: z.string().min(1),
  title: z.string(),
  section: z.string(),
  position: z.number().int().nonnegative(),
  text: z.string(),
  vector: z.array(z.number()),
});

const indexSchema = z.object({
  model: z.string().min(1),
  dim: z.number().int().positive(),
  strategy: z.enum(RAG_STRATEGIES),
  builtAt: z.string().min(1),
  chunks: z.array(chunkSchema),
});

export type RagChunk = z.infer<typeof chunkSchema>;
export type RagIndex = z.infer<typeof indexSchema>;

export type RagChunk = z.infer<typeof chunkSchema>;
export type RagIndex = z.infer<typeof indexSchema>;

export const compareStatsSchema = z.object({
  generatedAt: z.string().min(1),
  model: z.string().min(1),
  probes: z.number().int().nonnegative(),
  byStrategy: z.object({
    fixed: z.object({ hitAt1: z.number(), hitAt5: z.number(), mrr: z.number() }),
    structured: z.object({ hitAt1: z.number(), hitAt5: z.number(), mrr: z.number() }),
  }),
  buildStats: z.object({
    fixed: z
      .object({
        chunks: z.number().int().nonnegative(),
        avgChars: z.number(),
        medianChars: z.number(),
        p95Chars: z.number(),
        splitInsideBlockPct: z.number(),
        splitInsideSentencePct: z.number(),
        overlapPct: z.number().nullable(),
        buildTimeMs: z.number().nonnegative(),
      })
      .passthrough(),
    structured: z
      .object({
        chunks: z.number().int().nonnegative(),
        avgChars: z.number(),
        medianChars: z.number(),
        p95Chars: z.number(),
        splitInsideBlockPct: z.number(),
        splitInsideSentencePct: z.number(),
        overlapPct: z.number().nullable(),
        buildTimeMs: z.number().nonnegative(),
      })
      .passthrough(),
  }),
});

export type CompareStats = z.infer<typeof compareStatsSchema>;

export class RagUnavailableError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "RagUnavailableError";
  }
}

export type CompareStats = z.infer<typeof compareStatsSchema>;

/** Atomic write (tmp + rename) — house pattern (pipelines/scheduler). */
export async function writeJsonAtomic(filePath: string, data: unknown): Promise<void> {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  const tmp = `${filePath}.${process.pid}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(data), "utf8");
  await fs.rename(tmp, filePath);
}

function percentile(sorted: number[], p: number): number {
  if (sorted.length === 0) return 0;
  const idx = Math.min(sorted.length - 1, Math.ceil((p / 100) * sorted.length) - 1);
  return sorted[Math.max(0, idx)];
}

export interface StrategyStats {
  strategy: RagStrategy;
  model: string;
  dim: number;
  builtAt: string;
  chunks: number;
  /** Day21 fix-up (pick C): distinct source paths (full repo-relative — `file`
   *  is a basename and collides across dirs) + sum of chunk text lengths for
   *  the UI pipeline story; structured has no overlap → totalChars ≈ corpus. */
  fileCount: number;
  totalChars: number;
  avgChars: number;
  medianChars: number;
  p95Chars: number;
  splitInsideBlockPct: number;
  splitInsideSentencePct: number;
  overlapPct: number | null;
  buildTimeMs: number | null;
}

export interface SearchHit {
  chunk: RagChunk;
  score: number;
}

export interface ComparePublic {
  generatedAt: string;
  model: string;
  probes: number;
  byStrategy: CompareStats["byStrategy"];
}

export class RagService {
  private readonly indexDir: string;
  private readonly indexCache = new Map<RagStrategy, RagIndex>();
  private readonly embedders = new Map<string, Promise<Embedder>>();

constructor(private readonly env: Env) {
    this.indexDir = resolveFromRoot(env.RAG_INDEX_DIR, "data/rag");
  }

constructor(private readonly env: Env) {
    this.indexDir = resolveFromRoot(env.RAG_INDEX_DIR, "data/rag");
  }

private indexFile(strategy: RagStrategy): string {
    return path.join(this.indexDir, `rag-index-${strategy}.json`);
  }

async loadIndex(strategy: RagStrategy): Promise<RagIndex> {
    const cached = this.indexCache.get(strategy);
    if (cached) return cached;
    let raw: string;
    try {
      raw = await fs.readFile(this.indexFile(strategy), "utf8");
    } catch {
      throw new RagUnavailableError(`index missing: ${strategy}`);
    }
    let parsedJson: unknown;
    try {
      parsedJson = JSON.parse(raw);
    } catch {
      throw new RagUnavailableError(`index corrupt (JSON.parse): ${strategy}`);
    }
    const parsed = indexSchema.safeParse(parsedJson);
    if (!parsed.success) {
      throw new RagUnavailableError(`index schema mismatch: ${strategy}`);
    }
    const index = parsed.data;
    if (index.chunks.some((c) => c.vector.length !== index.dim)) {
      throw new RagUnavailableError(`index dim mismatch: ${strategy}`);
    }
    this.indexCache.set(strategy, index);
    return index;
  }

async stats(): Promise<{ ok: true; indexes: StrategyStats[]; compare: ComparePublic | null }> {
    const indexes = await Promise.all(RAG_STRATEGIES.map((s) => this.loadIndex(s)));
    const compare = await this.loadCompare();
    return {
      ok: true,
      indexes: indexes.map((index) => this.buildStats(index, compare?.buildStats[index.strategy] ?? null)),
      compare: compare
        ? {
            generatedAt: compare.generatedAt,
            model: compare.model,
            probes: compare.probes,
            byStrategy: compare.byStrategy,
          }
        : null,
    };
  }

private buildStats(index: RagIndex, build: CompareStats["buildStats"]["fixed"] | null): StrategyStats {
    const lengths = index.chunks.map((c) => c.text.length).sort((a, b) => a - b);
    const sum = lengths.reduce((acc, n) => acc + n, 0);
    return {
      strategy: index.strategy,
      model: index.model,
      dim: index.dim,
      builtAt: index.builtAt,
      chunks: index.chunks.length,
      fileCount: new Set(index.chunks.map((c) => c.source)).size,
      totalChars: sum,
      avgChars: lengths.length ? Math.round(sum / lengths.length) : 0,
      medianChars: percentile(lengths, 50),
      p95Chars: percentile(lengths, 95),
      splitInsideBlockPct: build?.splitInsideBlockPct ?? 0,
      splitInsideSentencePct: build?.splitInsideSentencePct ?? 0,
      overlapPct: build?.overlapPct ?? null,
      buildTimeMs: build?.buildTimeMs ?? null,
    };
  }

private async loadCompare(): Promise<CompareStats | null> {
    try {
      const raw = await fs.readFile(path.join(this.indexDir, "compare-stats.json"), "utf8");
      const parsed = compareStatsSchema.safeParse(JSON.parse(raw));
      if (!parsed.success) {
        console.warn("[rag/store] compare-stats.json schema mismatch — compare: null");
        return null;
      }
      return parsed.data;
    } catch {
      console.warn("[rag/store] compare-stats.json absent — compare: null");
      return null;
    }
  }

private async getEmbedder(model: string): Promise<Embedder> {
    let pending = this.embedders.get(model);
    if (!pending) {
      pending = createEmbedder(this.env, model).catch((err: unknown) => {
        this.embedders.delete(model);
        throw new RagUnavailableError(
          `embedder failure for ${model}: ${err instanceof Error ? err.message : String(err)}`,
        );
      });
      this.embedders.set(model, pending);
    }
    return pending;
  }

/** Day23 (design D-5): the FULL ranked list — search() minus the slice.
   *  Zero-regression refactor: the score loop is the original one. */
  async rankAll(query: string, strategy: RagStrategy): Promise<{ index: RagIndex; hits: SearchHit[] }> {
    return this.rankByQueries([query], strategy);
  }

/** Day23 rewrite-union (design D-4/D-5): embed every query (original +
   *  rewrite variants) and keep the PER-CHUNK MAX score — the original
   *  question can never be displaced (red-team guard). The embedder is
   *  private to RagService, so the union lives here, not in answer.ts
   *  (pass 02 F-3). */
  async rankByQueries(queries: string[], strategy: RagStrategy): Promise<{ index: RagIndex; hits: SearchHit[] }> {
    const index = await this.loadIndex(strategy);
    const embedder = await this.getEmbedder(index.model);
    const queryVectors: number[][] = [];
    for (const query of queries) {
      const vector = await embedder.embedQuery(query);
      if (vector.length !== index.dim) {
        throw new RagUnavailableError(`query dim ${vector.length} != index dim ${index.dim}`);
      }
      queryVectors.push(vector);
    }
    // Vectors are stored normalized → dot product == cosine.
    const hits: SearchHit[] = index.chunks.map((chunk) => {
      let best = -Infinity;
      for (const queryVector of queryVectors) {
        let score = 0;
        for (let i = 0; i < index.dim; i++) score += queryVector[i] * chunk.vector[i];
        if (score > best) best = score;
      }
      return { chunk, score: best };
    });
    hits.sort((a, b) => b.score - a.score);
    return { index, hits };
  }

async search(
    query: string,
    strategy: RagStrategy,
    k: number,
  ): Promise<{ index: RagIndex; hits: SearchHit[] }> {
    const { index, hits } = await this.rankAll(query, strategy);
    return { index, hits: hits.slice(0, k) };
  }
}

export function createRagService(env: Env): RagService {
  return new RagService(env);
}

/**
 * Day24 (design D-3, Δ-1): общий нормализатор русского текста — перенос из
 * eval-rag-answer.ts:87–94 без изменения логики; оба потребителя (серверная
 * верификация цитат в answer.ts, метрики eval) импортируют его отсюда.
