/** lowercase · ё→е · пунктуация → пробел · `\s+` → один пробел · trim. */
export function normalizeRu(s: string): string {
  return s
    .toLowerCase()
    .replace(/ё/g, "е")
    .replace(/[^a-zа-я0-9 ]+/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

