const SEEN_MAX = 1000;
const ARTICLES_MAX = 200;
const SUMMARIES_MAX = 50;
const FRESH_WINDOW_MS = 30 * 24 * 60 * 60 * 1000;
const ESEARCH_WINDOW_DAYS = 30;
const SUMMARY_BATCH_MAX = 3;
const ABSTRACT_CAP = 4000;
/** Design D-4: background summaries use deepseek-chat only (known price). */
const SUMMARY_MODEL = "deepseek-chat";
const SUMMARY_TIMEOUT_MS = 60_000;
const SUMMARY_MAX_TOKENS = 500;
/** Background ₽ gate keeps a margin below the user-facing budget ceiling. */
const BUDGET_MARGIN = 0.95;

const JobSchema = z.object({
  id: z.string(),
  query: z.string(),
  everySec: z.number().int().gte(30),
  ttlSec: z.number().int().positive(),
  createdAt: z.string(),
  expiresAt: z.string(),
  nextRunAt: z.number(),
  lastRunAt: z.number().nullable(),
  missed: z.number().int().nonnegative(),
  active: z.boolean(),
});

const ArticleSchema = z.object({
  pmid: z.string(),
  title: z.string(),
  journal: z.string(),
  pubdate: z.string(),
  epubdate: z.string(),
  authors: z.array(z.string()).max(3),
  query: z.string(),
  jobId: z.string().nullable(),
  fetchedAt: z.string(),
  state: z.enum(["pending", "digested"]),
  /** Informational only — nothing follows this link (pass 05 п.6). */
  summaryId: z.string().optional(),
});

const SummarySchema = z.object({
  id: z.string(),
  at: z.string(),
  mode: z.enum(["fresh", "archive"]),
  jobIds: z.array(z.string()),
  articles: z.array(
    z.object({ pmid: z.string(), title: z.string(), journal: z.string() }),
  ),
  text: z.string(),
});

const StoreSchema = z.object({
  version: z.literal(1),
  jobs: z.array(JobSchema),
  seenPmids: z.array(z.string()),
  articles: z.record(z.string(), ArticleSchema),
  summaries: z.array(SummarySchema),
  counters: z.object({
    ticks: z.number().int().nonnegative(),
    pubmedCalls: z.number().int().nonnegative(),
    pubmedErrors: z.number().int().nonnegative(),
    llmCalls: z.number().int().nonnegative(),
    skippedBudget: z.number().int().nonnegative(),
    missed: z.number().int().nonnegative(),
  }),
});

type Job = z.infer<typeof JobSchema>;
type Article = z.infer<typeof ArticleSchema>;
export type SchedulerSummary = z.infer<typeof SummarySchema>;
type Store = z.infer<typeof StoreSchema>;
type SchedulerCounters = Store["counters"];

type Job = z.infer<typeof JobSchema>;
type Article = z.infer<typeof ArticleSchema>;
export type SchedulerSummary = z.infer<typeof SummarySchema>;
type Store = z.infer<typeof StoreSchema>;
type SchedulerCounters = Store["counters"];

function emptyStore(): Store {
  return {
    version: 1,
    jobs: [],
    seenPmids: [],
    articles: {},
    summaries: [],
    counters: {
      ticks: 0,
      pubmedCalls: 0,
      pubmedErrors: 0,
      llmCalls: 0,
      skippedBudget: 0,
      missed: 0,
    },
  };
}

/**
 * Boot restore: skip-and-advance — сдвигает `nextRunAt` за `now`,
 * накапливает missed. Без PubMed/таймеров (гейт 261009 D-2).
 * Мутирует job in-place; возвращает число пропущенных тиков этого прохода.
 */
export function countAndAdvanceMissedTicks(
  job: { nextRunAt: number; everySec: number; missed: number },
  now: number,
): number {
  if (job.nextRunAt > now) return 0;
  let missed = 0;
  while (job.nextRunAt <= now) {
    job.nextRunAt += job.everySec * 1000;
    missed += 1;
  }
  job.missed += missed;
  return missed;
}

/** Джоба протухла по TTL (expiresAt). */
export function isJobExpired(
  job: { expiresAt: string },
  now: number,
): boolean {
  return now > Date.parse(job.expiresAt);
}

/* ------------------------------ Service ---------------------------------- */

export class SchedulerService {
  private store: Store = emptyStore();
  private chain: Promise<unknown> = Promise.resolve();
  private tickTimer: NodeJS.Timeout | null = null;
  private summaryTimer: NodeJS.Timeout | null = null;
  private running = false;

constructor(
    private readonly opts: {
      file: string;
      env: Env;
      deepSeek: DeepSeekService;
      ledger: UsageLedgerService;
    },
  ) {}

constructor(
    private readonly opts: {
      file: string;
      env: Env;
      deepSeek: DeepSeekService;
      ledger: UsageLedgerService;
    },
  ) {}

/** Restore store from disk; broken file → empty store + warn (design §4.2). */
  async load(): Promise<void> {
    try {
      const raw = await fs.readFile(this.opts.file, "utf8");
      const parsed = StoreSchema.safeParse(JSON.parse(raw));
      if (parsed.success) {
        this.store = parsed.data;
      } else {
        console.warn("[scheduler] store parse failed — starting empty");
        this.store = emptyStore();
      }
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code !== "ENOENT") {
        console.warn("[scheduler] store load failed — starting empty");
      }
      this.store = emptyStore();
    }
  }

start(): void {
    this.running = true;
    void this.restoreAndStart();
  }

stop(): void {
    this.running = false;
    if (this.tickTimer) clearTimeout(this.tickTimer);
    if (this.summaryTimer) clearTimeout(this.summaryTimer);
    this.tickTimer = null;
    this.summaryTimer = null;
  }

snapshot(): {
    jobs: Job[];
    counters: SchedulerCounters & {
      pending: number;
      digested: number;
      articles: number;
    };
    lastSummary: SchedulerSummary | null;
  } {
    const all = Object.values(this.store.articles);
    return {
      jobs: this.store.jobs,
      counters: {
        ...this.store.counters,
        pending: all.filter((a) => a.state === "pending").length,
        digested: all.filter((a) => a.state === "digested").length,
        articles: all.length,
      },
      lastSummary: this.store.summaries[0] ?? null,
    };
  }

/** MCP tool schedule_job. Throws "job_cap_reached" when active cap hit. */
  async scheduleJob(input: {
    query: string;
    everySec: number;
    ttlSec?: number;
  }): Promise<{ jobId: string; nextRunAt: string; active: true }> {
    const activeCount = this.store.jobs.filter((j) => j.active).length;
    if (activeCount >= ACTIVE_JOBS_MAX) {
      throw new Error("job_cap_reached");
    }
    const ttlSec = input.ttlSec ?? 86_400;
    const now = Date.now();
    const job: Job = {
      id: `job-${randomUUID().slice(0, 8)}`,
      query: input.query,
      everySec: input.everySec,
      ttlSec,
      createdAt: new Date(now).toISOString(),
      expiresAt: new Date(now + ttlSec * 1000).toISOString(),
      nextRunAt: now,
      lastRunAt: null,
      missed: 0,
      active: true,
    };
    // Whole-jobs cap (pass 04 п.1): FIFO by createdAt, prefer evicting inactive.
    while (this.store.jobs.length >= JOBS_MAX) {
      const order = [...this.store.jobs].sort((a, b) =>
        a.createdAt.localeCompare(b.createdAt),
      );
      const victim = order.find((j) => !j.active) ?? order[0];
      this.store.jobs = this.store.jobs.filter((j) => j.id !== victim.id);
    }
    this.store.jobs.push(job);
    await this.persist();
    this.scheduleNextTick();
    return {
      jobId: job.id,
      nextRunAt: new Date(job.nextRunAt).toISOString(),
      active: true,
    };
  }

cancelJob(id: string): boolean {
    const job = this.store.jobs.find((j) => j.id === id);
    if (!job) return false;
    job.active = false;
    void this.persist();
    return true;
  }

/* ------------------------------ internals ------------------------------ */

cancelJob(id: string): boolean {
    const job = this.store.jobs.find((j) => j.id === id);
    if (!job) return false;
    job.active = false;
    void this.persist();
    return true;
  }

/** Boot restore: expire, skip-and-advance missed ticks, ≤1 catch-up tick. */
  private async restoreAndStart(): Promise<void> {
    const now = Date.now();
    let mostOverdue: Job | null = null;
    for (const job of this.store.jobs) {
      if (!job.active) continue;
      if (isJobExpired(job, now)) {
        job.active = false;
        continue;
      }
      if (job.nextRunAt <= now) {
        const missed = countAndAdvanceMissedTicks(job, now);
        this.store.counters.missed += missed;
        if (!mostOverdue || job.nextRunAt < mostOverdue.nextRunAt) {
          mostOverdue = job;
        }
      }
    }
    if (mostOverdue) {
      await this.runJobTick(mostOverdue, false);
    }
    await this.persist();
    if (this.running) {
      this.scheduleNextTick();
      this.scheduleSummaryTimer();
    }
  }

private scheduleNextTick(): void {
    if (this.tickTimer) clearTimeout(this.tickTimer);
    if (!this.running) return;
    const active = this.store.jobs.filter((j) => j.active);
    if (active.length === 0) return;
    const next = Math.min(...active.map((j) => j.nextRunAt));
    const delay = Math.max(0, next - Date.now());
    this.tickTimer = setTimeout(() => {
      void this.onTick();
    }, delay);
  }

private async onTick(): Promise<void> {
    if (!this.running) return;
    const now = Date.now();
    for (const job of this.store.jobs) {
      if (!job.active) continue;
      if (now > Date.parse(job.expiresAt)) {
        job.active = false;
        continue;
      }
      if (job.nextRunAt <= now) {
        await this.runJobTick(job);
      }
    }
    await this.persist();
    await this.maybeRunSummary();
    this.scheduleNextTick();
  }

/** PubMed collection — no LLM, ₽0 (design §4.1 TICK). */
  private async runJobTick(job: Job, advance = true): Promise<void> {
    job.lastRunAt = Date.now();
    if (advance) {
      job.nextRunAt = Date.now() + job.everySec * 1000;
    }
    this.store.counters.ticks += 1;
    try {
      const search = await esearch(job.query, {
        retmax: 20,
        reldateDays: ESEARCH_WINDOW_DAYS,
      });
      this.store.counters.pubmedCalls += 1;
      const known = new Set(this.store.seenPmids);
      const freshPmids = search.pmids.filter((p) => !known.has(p));
      if (freshPmids.length > 0) {
        const metas = await esummary(freshPmids);
        this.store.counters.pubmedCalls += 1;
        // Room first: overflow with no digested candidates drops new items
        // (pass 04 п.2) — unseen pmids stay unseen and retry next tick.
        const room = this.makeRoomForArticles(freshPmids.length);
        let added = 0;
        for (const pmid of freshPmids) {
          if (added >= room) break;
          const meta = metas.get(pmid);
          if (!meta) continue;
          // seen+metadata is one atomic mutation (pass 04 п.3) — an esummary
          // miss never burns the pmid.

this.store.seenPmids.push(pmid);
          this.store.articles[pmid] = {
            pmid,
            title: meta.title,
            journal: meta.journal,
            pubdate: meta.pubdate,
            epubdate: meta.epubdate,
            authors: meta.authors,
            query: job.query,
            jobId: job.id,
            fetchedAt: new Date().toISOString(),
            state: "pending",
          };
          added += 1;
        }
        this.trimSeen();
        if (added < freshPmids.length) {
          this.store.counters.pubmedErrors += 1;
        }
      }
    } catch {
      this.store.counters.pubmedErrors += 1;
    }
  }

private makeRoomForArticles(n: number): number {
    const entries = Object.entries(this.store.articles);
    let room = Math.max(0, ARTICLES_MAX - entries.length);
    if (room >= n) return room;
    const digested = entries
      .filter(([, a]) => a.state === "digested")
      .sort((a, b) => a[1].fetchedAt.localeCompare(b[1].fetchedAt));
    for (const [pmid] of digested) {
      if (room >= n) break;
      delete this.store.articles[pmid];
      room += 1;
    }
    return room;
  }

private trimSeen(): void {
    while (this.store.seenPmids.length > SEEN_MAX) {
      this.store.seenPmids.shift();
    }
  }

private pendingArticles(): Article[] {
    return Object.values(this.store.articles).filter(
      (a) => a.state === "pending",
    );
  }

private lastJobQuery(): string {
    const [latest] = [...this.store.jobs].sort((a, b) =>
      b.createdAt.localeCompare(a.createdAt),
    );
    return latest?.query ?? DEFAULT_QUERY;
  }

/** Proactive digest — the only LLM caller in the scheduler (design §4.1). */
  private async maybeRunSummary(): Promise<void> {
    if (!this.running) return;
    if (!this.debouncePassed()) return;
    const hadMaterial = await this.ensureMaterial();
    if (!hadMaterial) return;
    if (!(await this.budgetAllows())) {
      this.store.counters.skippedBudget += 1;
      await this.persist();
      return;
    }
    await this.generateSummary();
    await this.persist();
    this.scheduleSummaryTimer();
  }

private debouncePassed(): boolean {
    if (this.store.summaries.length === 0) return true; // first summary fires at once
    const latest = this.store.summaries[0]?.at;
    if (!latest) return true;
    const minMs = this.opts.env.SCHEDULE_SUMMARY_MIN_SEC * 1000;
    return Date.now() - Date.parse(latest) >= minMs;
  }

private async ensureMaterial(): Promise<boolean> {
    if (this.pendingArticles().length > 0) return true;
    // archive-idle path (pending==0): deep-fetch a random history page.
    const term = this.lastJobQuery();
    try {
      const search = await esearch(term, { retmax: 1, retstart: randomInt(0, 300) });
      this.store.counters.pubmedCalls += 1;
      const known = new Set(this.store.seenPmids);
      const candidates = search.pmids.filter((p) => !known.has(p));
      if (candidates.length === 0) return false; // known pmid → skip this round
      const metas = await esummary(candidates);
      this.store.counters.pubmedCalls += 1;
      const room = this.makeRoomForArticles(1);
      if (room === 0) return false;
      for (const pmid of candidates) {
        const meta = metas.get(pmid);
        if (!meta) continue;
        this.store.seenPmids.push(pmid);
        this.store.articles[pmid] = {
          pmid,
          title: meta.title,
          journal: meta.journal,
          pubdate: meta.pubdate,
          epubdate: meta.epubdate,
          authors: meta.authors,
          query: term,
          jobId: null,
          fetchedAt: new Date().toISOString(),
          state: "pending",
        };
        this.trimSeen();
        return true;
      }
      return false;
    } catch {
      this.store.counters.pubmedErrors += 1;
      return false;
    }
  }

private async budgetAllows(): Promise<boolean> {
    const limit = this.opts.env.DAILY_BUDGET_RUB;
    if (limit <= 0) return true;
    const totals = await this.opts.ledger.getTotals();
    return (totals.cost_rub_today ?? 0) < limit * BUDGET_MARGIN;
  }

private async budgetAllows(): Promise<boolean> {
    const limit = this.opts.env.DAILY_BUDGET_RUB;
    if (limit <= 0) return true;
    const totals = await this.opts.ledger.getTotals();
    return (totals.cost_rub_today ?? 0) < limit * BUDGET_MARGIN;
  }

private async generateSummary(): Promise<void> {
    const pending = this.pendingArticles();
    const freshCutoff = Date.now() - FRESH_WINDOW_MS;
    const byFetched = (a: Article, b: Article) =>
      a.fetchedAt.localeCompare(b.fetchedAt);
    const fresh = pending
      .filter((a) => Date.parse(a.fetchedAt) >= freshCutoff)
      .sort(byFetched)
      .slice(0, SUMMARY_BATCH_MAX);
    let mode: "fresh" | "archive";
    let batch: Article[];
    if (fresh.length > 0) {
      mode = "fresh";
      batch = fresh;
    } else if (pending.length > 0) {
      mode = "archive";
      batch = [pending.sort(byFetched)[0]];
    } else {
      return;
    }

const blocks: string[] = [];
    const refs: SchedulerSummary["articles"] = [];
    for (const article of batch) {
      try {
        const text = (await efetchAbstract(article.pmid)).slice(0, ABSTRACT_CAP);
        this.store.counters.pubmedCalls += 1;
        blocks.push(
          `PMID ${article.pmid} — «${article.title}» (${article.journal}, ${article.pubdate}):\n${text}`,
        );
        refs.push({
          pmid: article.pmid,
          title: article.title,
          journal: article.journal,
        });
      } catch {
        this.store.counters.pubmedErrors += 1;
      }
    }
    if (blocks.length === 0) return;

const jobIds = [
      ...new Set(
        batch
          .map((a) => a.jobId)
          .filter((id): id is string => Boolean(id)),
      ),
    ];
    try {
      const result = await this.opts.deepSeek.chat(
        [
          { role: "system", content: summarySystemPrompt(mode) },
          {
            role: "user",
            content:
              `${blocks.join("\n\n")}\n\n` +
              "Сделай по-русски краткий дайджест (3–5 предложений): что изучали, " +
              "главный результат, практический смысл при мышечной боли.",
          },
        ],
        {
          model: SUMMARY_MODEL,
          maxTokens: SUMMARY_MAX_TOKENS,
          timeoutMs: SUMMARY_TIMEOUT_MS,
          temperature: 0.4,
        },
      );
      // Background call is accounted like any other (design D-4/TR-7).

await this.opts.ledger.record(result.usage);
      const summary: SchedulerSummary = {
        id: `sum-${Date.now()}`,
        at: new Date().toISOString(),
        mode,
        jobIds,
        articles: refs,
        text: result.reply,
      };
      this.store.summaries.unshift(summary);
      if (this.store.summaries.length > SUMMARIES_MAX) {
        this.store.summaries.length = SUMMARIES_MAX;
      }
      for (const article of batch) {
        const stored = this.store.articles[article.pmid];
        if (stored) {
          stored.state = "digested";
          stored.summaryId = summary.id;
        }
      }
      this.store.counters.llmCalls += 1;
      // C+ CH-6 (D-10): серверных тредов больше нет — доставка сводки в
      // личный чат снята; сводки живут в store и отдаются публично
      // (snapshot → MCP-атлас), «сводки не в личных чатах» (таблица D-4).
    } catch (error) {
      console.warn(
        "[scheduler] summary LLM call failed:",
        error instanceof Error ?

error.message : error,
      );
    }
  }

private scheduleSummaryTimer(): void {
    if (this.summaryTimer) clearTimeout(this.summaryTimer);
    if (!this.running) return;
    const minMs = this.opts.env.SCHEDULE_SUMMARY_MIN_SEC * 1000;
    const latest = this.store.summaries[0]?.at;
    const delay = latest
      ? Math.max(0, Date.parse(latest) + minMs - Date.now())
      : 0;
    this.summaryTimer = setTimeout(() => {
      void this.maybeRunSummary().then(() => this.scheduleSummaryTimer());
    }, delay);
  }

/** Serialized atomic writes (tmp+rename) — same pattern as usage-ledger. */
  private persist(): Promise<void> {
    const run = this.chain.then(
      () => this.writeStore(),
      () => this.writeStore(),
    );
    this.chain = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

private async writeStore(): Promise<void> {
    await fs.mkdir(path.dirname(this.opts.file), { recursive: true });
    const tmp = `${this.opts.file}.${process.pid}.tmp`;
    await fs.writeFile(tmp, `${JSON.stringify(this.store, null, 2)}\n`, "utf8");
    await fs.rename(tmp, this.opts.file);
  }
}

function randomInt(minInclusive: number, maxExclusive: number): number {
  return minInclusive + Math.floor(Math.random() * (maxExclusive - minInclusive));
}

function randomInt(minInclusive: number, maxExclusive: number): number {
  return minInclusive + Math.floor(Math.random() * (maxExclusive - minInclusive));
}

function summarySystemPrompt(mode: "fresh" | "archive"): string {
  const scope =
    mode === "fresh"
      ? "Это сводка по свежим публикациям последних недель."
      : "Свежих публикаций нет — это ретро-обзор одной более ранней статьи из архива.";
  return (
    "Ты готовишь краткий дайджест научных публикаций PubMed для приложения " +
    "самомассажа Trigger Helper. " +
    scope +
    " Отвечай по-русски, 3–5 предложений: что изучали, главный результат, " +
    "практический смысл для человека с мышечной болью. Ничего не выдумывай — " +
    "используй только предоставленные материалы; если данных мало, так и скажи."
  );
}

export function createSchedulerService(opts: {
  env: Env;
  deepSeek: DeepSeekService;
  ledger: UsageLedgerService;
}): SchedulerService {
  const file = opts.env.SCHEDULER_FILE
    ? path.resolve(opts.env.SCHEDULER_FILE)
    : path.join(repoRoot, "var", "scheduler.json");
  return new SchedulerService({ ...opts, file });
}

import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import type { LlmUsage, UsageModelBucket, UsageTotals } from "@trigger-helper/shared";
import { isExpensiveModel, todayMoscowDate } from "./model-cost-tier.js";
import { costRubFromUsage } from "./pricing.js";

const repoRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../../..",
);

function emptyBucket(): UsageModelBucket {
  return {
    requests: 0,
    cost_usd: 0,
    cost_rub: 0,
    total_tokens: 0,
    cache_hit_tokens: 0,
  };
}

function emptyTotals(): UsageTotals {
  const day = todayMoscowDate();
  return {
    requests: 0,
    cost_usd: 0,
    cost_rub: 0,
    total_tokens: 0,
    cache_hit_tokens: 0,
    by_model: {},
    expensive_day: day,
    expensive_asks_today: 0,
    budget_day: day,
    cost_rub_today: 0,
    cost_rub_expensive_today: 0,
    updated_at: new Date(0).toISOString(),
  };
}

function parseBucket(raw: unknown): UsageModelBucket {
  if (!raw || typeof raw !== "object") return emptyBucket();
  const o = raw as Record<string, unknown>;
  return {
    requests: Number(o.requests) || 0,
    cost_usd: Number(o.cost_usd) || 0,
    cost_rub: Number(o.cost_rub) || 0,
    total_tokens: Number(o.total_tokens) || 0,
    cache_hit_tokens: Number(o.cache_hit_tokens) || 0,
  };
}

/** Roll Moscow-day counters (asks + ₽ budgets). */
function withTodayCounters(totals: UsageTotals): UsageTotals {
  const today = todayMoscowDate();
  const sameExp = totals.expensive_day === today;
  const sameBudget = totals.budget_day === today;
  if (sameExp && sameBudget) {
    return totals;
  }
  return {
    ...totals,
    expensive_day: today,
    expensive_asks_today: sameExp ? (totals.expensive_asks_today ?? 0) : 0,
    budget_day: today,
    cost_rub_today: sameBudget ? (totals.cost_rub_today ?? 0) : 0,
    cost_rub_expensive_today: sameBudget
      ? (totals.cost_rub_expensive_today ?? 0)
      : 0,
  };
}

/**
 * Append-only style totals on disk (VPS). One JSON file, serialized writes.
 * Default path: <repo>/var/usage-totals.json (gitignored).
 */
export class UsageLedgerService {
  private chain: Promise<unknown> = Promise.resolve();
  private memory: UsageTotals | null = null;

constructor(private readonly filePath: string) {}

async getTotals(): Promise<UsageTotals> {
    return this.enqueue(async () => withTodayCounters(await this.readUnlocked()));
  }

/** Expensive asks used today (Moscow day), after rolling the day if needed. */
  async getExpensiveAsksToday(): Promise<number> {
    const totals = await this.getTotals();
    return totals.expensive_asks_today ?? 0;
  }

async record(
    usage: LlmUsage,
    opts: { countExpensive?: boolean } = {},
  ): Promise<UsageTotals> {
    const countExpensive = opts.countExpensive !== false;
    return this.enqueue(async () => {
      const current = withTodayCounters(await this.readUnlocked());
      const providerRub = usage.estimated_cost_rub ?? 0;
      const billingRub = costRubFromUsage(usage);
      const prev = current.by_model[usage.model] ?? emptyBucket();
      const nextBucket: UsageModelBucket = {
        requests: prev.requests + 1,
        cost_usd: Number((prev.cost_usd + usage.estimated_cost_usd).toFixed(6)),
        cost_rub: Number((prev.cost_rub + providerRub).toFixed(4)),
        total_tokens: prev.total_tokens + usage.total_tokens,
        cache_hit_tokens: prev.cache_hit_tokens + usage.prompt_cache_hit_tokens,
      };
      const expensive = isExpensiveModel(usage.model);
      const expensiveBump = countExpensive && expensive ? 1 : 0;
      const next: UsageTotals = {
        requests: current.requests + 1,
        cost_usd: Number(
          (current.cost_usd + usage.estimated_cost_usd).toFixed(6),
        ),
        cost_rub: Number((current.cost_rub + providerRub).toFixed(4)),
        total_tokens: current.total_tokens + usage.total_tokens,
        cache_hit_tokens:
          current.cache_hit_tokens + usage.prompt_cache_hit_tokens,
        by_model: { ...current.by_model, [usage.model]: nextBucket },
        expensive_day: current.expensive_day ?? todayMoscowDate(),
        expensive_asks_today:
          (current.expensive_asks_today ?? 0) + expensiveBump,
        budget_day: current.budget_day ?? todayMoscowDate(),
        cost_rub_today: Number(
          ((current.cost_rub_today ??

billingRub : 0)
          ).toFixed(4),
        ),
        updated_at: new Date().toISOString(),
      };
      await this.writeUnlocked(next);
      this.memory = next;
      return next;
    });
  }

private enqueue<T>(fn: () => Promise<T>): Promise<T> {
    const run = this.chain.then(fn, fn);
    this.chain = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

private async readUnlocked(): Promise<UsageTotals> {
    if (this.memory) {
      return this.memory;
    }
    try {
      return await this.parseFile(this.filePath);
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code === "ENOENT") {
        const restored = await this.tryRestoreFromBackup();
        if (restored) {
          return restored;
        }
        const empty = emptyTotals();
        this.memory = empty;
        return empty;
      }
      throw error;
    }
  }

private async parseFile(filePath: string): Promise<UsageTotals> {
    const raw = await fs.readFile(filePath, "utf8");
    const parsed = JSON.parse(raw) as Partial<UsageTotals> & {
      by_model?: Record<string, unknown>;
    };
    const by_model: Record<string, UsageModelBucket> = {};
    if (parsed.by_model && typeof parsed.by_model === "object") {
      for (const [key, value] of Object.entries(parsed.by_model)) {
        by_model[key] = parseBucket(value);
      }
    }
    const totals: UsageTotals = {
      requests: Number(parsed.requests) || 0,
      cost_usd: Number(parsed.cost_usd) || 0,
      cost_rub: Number(parsed.cost_rub) || 0,
      total_tokens: Number(parsed.total_tokens) || 0,
      cache_hit_tokens: Number(parsed.cache_hit_tokens) || 0,
      by_model,
      expensive_day:
        typeof parsed.expensive_day === "string"
          ? parsed.expensive_day
          : undefined,
      expensive_asks_today: Number(parsed.expensive_asks_today) || 0,
      budget_day:
        typeof parsed.budget_day === "string" ? parsed.budget_day : undefined,
      cost_rub_today: Number(parsed.cost_rub_today) || 0,
      cost_rub_expensive_today: Number(parsed.cost_rub_expensive_today) || 0,
      updated_at:
        typeof parsed.updated_at === "string"
          ? parsed.updated_at
          : new Date(0).toISOString(),
    };
    this.memory = totals;
    return totals;
  }

/** If live ledger missing, copy newest var/backups/usage-totals-*.json. */
  private async tryRestoreFromBackup(): Promise<UsageTotals | null> {
    const backupDir = path.join(path.dirname(this.filePath), "backups");
    let names: string[];
    try {
      names = await fs.readdir(backupDir);
    } catch {
      return null;
    }
    const candidates = names
      .filter((n) => /^usage-totals-.+\.json$/.test(n))
      .sort()
      .reverse();
    for (const name of candidates) {
      const bakPath = path.join(backupDir, name);
      try {
        const totals = await this.parseFile(bakPath);
        if ((totals.requests ?? 0) <= 0 && (totals.cost_rub ?? 0) <= 0) {
          continue;
        }
        await fs.mkdir(path.dirname(this.filePath), { recursive: true });
        await fs.copyFile(bakPath, this.filePath);
        return totals;
      } catch {
        // try older backup
      }
    }
    return null;
  }

private async writeUnlocked(totals: UsageTotals): Promise<void> {
    await fs.mkdir(path.dirname(this.filePath), { recursive: true });
    const tmp = `${this.filePath}.${process.pid}.tmp`;
    await fs.writeFile(tmp, `${JSON.stringify(totals, null, 2)}\n`, "utf8");
    await fs.rename(tmp, this.filePath);
  }
}

export function createUsageLedgerService(
  customPath?: string,
): UsageLedgerService {
  const filePath = customPath
    ? path.resolve(customPath)
    : path.join(repoRoot, "var", "usage-totals.json");
  return new UsageLedgerService(filePath);
}

import type { LlmUsage } from "@trigger-helper/shared";

/** Sum usage across multi-call flows (meta, etc.). */
export function mergeUsage(parts: LlmUsage[]): LlmUsage {
  if (parts.length === 0) {
    throw new Error("mergeUsage requires at least one usage");
  }
  if (parts.length === 1) {
    return parts[0]!;
  }

const model = parts[parts.length - 1]!.model;
  let prompt_tokens = 0;
  let completion_tokens = 0;
  let total_tokens = 0;
  let prompt_cache_hit_tokens = 0;
  let prompt_cache_miss_tokens = 0;
  let estimated_cost_usd = 0;
  let estimated_cost_rub = 0;

for (const u of parts) {
    prompt_tokens += u.prompt_tokens;
    completion_tokens += u.completion_tokens;
    total_tokens += u.total_tokens;
    prompt_cache_hit_tokens += u.prompt_cache_hit_tokens;
    prompt_cache_miss_tokens += u.prompt_cache_miss_tokens;
    estimated_cost_usd += u.estimated_cost_usd;
    estimated_cost_rub += u.estimated_cost_rub ?? 0;
  }

return {
    model,
    prompt_tokens,
    completion_tokens,
    total_tokens,
    prompt_cache_hit_tokens,
    prompt_cache_miss_tokens,
    estimated_cost_usd: Number(estimated_cost_usd.toFixed(6)),
    estimated_cost_rub: Number(estimated_cost_rub.toFixed(4)),
  };
}

